                && (mean_residual as u32) < item_size;
            if open_all_bad {
                score -= 5.0 + 6.0 * t;
            } else {
                score += 4.0 + 5.0 * t;
            }
        }
        // MUTATION (refined): grade the fresh bin's leftover by next-item tileability
        if next_item_size > 0 && left_after > 0 {
            let la = left_after as f64;
            let nxt = next_item_size as f64;
            if la >= nxt {
                let rem = left_after % next_item_size;
                if rem == 0 {
                    score -= 16.0 + 7.0 * t;
                } else if rem <= 3 {
                    score -= 8.0 + 3.0 * t;
                }
            } else {
                let shortfall = nxt - la;
                if shortfall <= 8.0 {
                    score += 3.0 + 1.5 * shortfall * (0.4 + t);
                }
            }
        }
        // MUTATION: near-pair overflow — an open bin may still host the next item
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            let overflow = (item_size + next_item_size - bin_capacity) as f64;
            if overflow <= 10.0 {
                score += 2.0 + 0.4 * overflow;
            }
        }
        // MUTATION: single-fit waste guard — don't open fresh when the only
        // fitting open bin would waste little
        if fitting_bins_count == 1 && open_bins_count <= 3 && mean_residual > 0.0 {
            let waste = mean_residual - item_size as f64;
            if waste > 0.0 {
                score += 3.0 + 0.3 * waste.min(30.0);
            }
        }
        // MUTATION: late-stream fresh-bin guard — resist opening fresh bins
        // near the end unless the item is large
        if t > 0.85 && fitting_bins_count >= 1 && item_size < bin_capacity / 2 {
            score += 10.0 * t;
        }
    } else {
        score += (bin_capacity as f64 - bin_residual as f64) * 0.1;
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
        if fitting_bins_count >= 2 && pr > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((pr as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / fitting_bins_count as f64);
        }
        if t > 0.7 && pr <= 20 {
            score -= 13.0 * t;
        }
        if t > 0.4 && pr > 0 && pr < 15 {
            score += 5.0 * (1.0 - t);
        }
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        let tightness = 1.0 - ((pr as f64 - item_size as f64).abs() / 30.0).min(1.0);
        score -= 8.0 * tightness * (0.3 + 0.7 * t);
        if pr > 15 && pr < 45 {
            score += 0.35 * (pr as f64 - 15.0);
        }
        if next_item_size > 0 && pr > 0 && pr % next_item_size == 0 {
            score -= 10.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr > 0 {
            score -= 6.0;
            if pr - next_item_size <= 5 {
                score -= 11.0;
            }
        }
        if t > 0.6 && pr > 0 && pr <= item_size / 4 {
            score -= 10.0 * t;
        }
        if t > 0.75 && pr > 0 && pr <= 8 && open_bins_count > 4 {
            score -= 14.0 * t;
        }
        if t > 0.55 && t <= 0.75 && pr > 0 && pr <= 6 && open_bins_count > 6 {
            score -= 8.0 * t;
        }
        if pr > 0 && pr < 4 && t > 0.8 {
            score += 10.0;
        }
        if pr > 0 && pr < 5 && next_item_size > pr {
            score += 9.0 + 6.0 * t;
        }
        // Penalize bins whose post residual cannot host the next item
