        // MUTATION: variance suppression — homogenize residuals when fragmented
        if pr > 0 && open_bins_count > 5 && mean_residual > 0.0 {
            let dev = (pr as f64 - mean_residual).abs();
            if dev > 10.0 {
                score += 0.25 * (dev - 10.0).min(25.0) * (0.4 + 0.6 * t);
            }
        }
        // MUTATION: endgame squeeze — late, prioritize exact next-item fills
        if t > 0.8 && pr > 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / 20.0).max(0.0);
        }
        // MUTATION: dead-space ratio gradient
        if pr > 0 && next_item_size > 0 && next_item_size > pr {
            let dead_frac = pr as f64 / bin_capacity as f64;
            if dead_frac > 0.25 {
                score += 4.0 * (dead_frac - 0.25) * (1.0 + open_bins_count.min(20) as f64 * 0.05);
            }
        }
        // MUTATION: pair-completion bonus
        if pr > 0 && next_item_size > 0 && pr > next_item_size {
            let rest = pr - next_item_size;
            if rest >= 10 && rest <= 30 && (rest as f64 - mean_residual).abs() <= 2.0 {
                score -= 8.0;
            }
        }
        // MUTATION: residual cliff guard — avoid leaving a residual just below
        // the next item (nearly unusable), strongest mid-stream
        if pr > 0 && next_item_size > 0 && pr < next_item_size {
            let gap = next_item_size - pr;
            if gap <= 6 {
