    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item leaves this residual unusable, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are healthy.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 3.0 * pressure * (mean_residual / bin_capacity as f64);

    // New-bin candidate: default slightly worse than a decent fit, but becomes
    // attractive when all open fits are poor (large dead space would result).
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a bin early in the stream is cheaper (more items to fill it later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If the only fitting bins would leave unusable dead space, prefer a new bin.
        if post_residual == 0 && item_size > 0 {
            // brand-new bin keeps full residual; handled by base score already
        }
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that can never fit even the smallest future item (size 1)
    // is only zero-cost if it's 0; small residuals are "dead" if below
    // a plausible future item size. Use a soft threshold around 10-30.
    let dead_threshold = 20.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // from the mean in a useful way (large residual bins absorb big items).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 15.0;

    // Open bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening new bins is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.8;

    // Lookahead: if the next item fits into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving residual that is
        // close to but below next item size (near-miss dead space).
        let gap = next_item_size - post_residual;
        if gap <= 15 {
            score += gap as f64 * 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when the
    // current item is large relative to available residuals or when
    // residuals across bins are small (poor fits everywhere).
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / bin_capacity as f64;
        // Open new bin if mean residual is small (existing bins are full-ish)
        score = 10.0 + avg_fit * 40.0;
        // But if this bin is a last resort, still prefer it over new bin
        if fitting_bins_count == 1 {
            score += 45.0;
        }
        // Early stream: new bins are cheap
        score -= (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- 2-step lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
