    score -= 0.15 * (bin_capacity as f64 - post_residual as f64);

    // --- Last-chance bin: strongly favor using it to avoid opening a bin ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // --- Mean residual coupling: prefer bins whose residual is below mean
    //     (pack into the emptiest-feeling tight bins, keep loose bins open) ---
    score += 0.3 * (mean_residual - post_residual as f64);

