        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        // If no open bin fits well (this bin is the only fitting candidate), opening is fine.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Lookahead synergy: fresh bin can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = pr;

    // Non-linear coupling: squared normalized residual interacting with stream progress
    let norm_pr = pr / cap;
    let sq = norm_pr * norm_pr;
    score += sq * (4.0 + 8.0 * progress);

    // Cubic dead-space penalty that grows late in the stream
    let cu = norm_pr * sq;
    score += cu * (6.0 * progress + 2.0);

    // Reward tight fits: smooth exponential decay on post_residual
    score -= 6.0 * (-pr / 12.0).exp();

    // Lookahead coupling: penalize if next item fits perfectly in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 5.0 * (-gap / 10.0).exp();
        } else {
            score += 1.5 * ((nxt - pr) / 20.0);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // Mild penalty when bin residual deviates from mean residual (favor homogeneity)
    score += 0.3 * (pr - mean_residual).abs();

    // Slight preference for using existing bins as stream progresses
    score += 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "waste band" does it fall in?
    // Bands keyed on integer division by 10 (capacity fractions).
    let band = post_residual / 10;
    match band {
        0 => score -= 40.0,                      // near-perfect fill
        1 => score -= 25.0,                      // excellent fill
        2 => score -= 12.0,                      // good fill
        3 => score -= 4.0,
        4 | 5 => score += 6.0,                   // mediocre
        6 | 7 => score += 15.0,                  // large dead space
        _ => score += 25.0,                      // mostly empty
    }

    // Modulo-5 harmonic penalty: residuals that are multiples of 5 are
    // "harmonic" with common item sizes (which cluster on multiples of 5),
    // so they are more likely to be filled by future items.
    if post_residual % 5 == 0 {
        score -= 8.0;
    } else {
        score += (5 - post_residual % 5) as f64; // non-harmonic waste penalty
    }

    // Lookahead coupling: reward residuals that can exactly host the next item,
    // or at least fit it comfortably.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize proportionally to the gap.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance logic: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If many bins are open with lots of average residual, opening new is worse.
        score += mean_residual * 0.2;
    }

    // Stream progression: late in the stream, close out bins more aggressively
    // (prefer tighter fills to avoid many half-empty leftovers).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.3;
    score += progress * 10.0 * (open_bins_count as f64).ln().max(0.0);

    // Penalize bins whose residual deviates far from the mean residual
    // (prefer balanced residual distribution).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // (items are 1..=100 but small gaps waste capacity), so penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Medium gap: mildly bad, still usable by small items.
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into the resulting gap,
    // strongly favor this bin; if the gap can hold the next item at all,
    // mild favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit in the gap: the residual becomes dead space
            // unless it's large; penalize small leftovers more.
            if post_residual < next_item_size {
                score += 12.0;
            }
        }
    }

    // Open-bin pressure: with many open bins, prefer placements that tighten
    // existing bins rather than spreading; reward choosing bins below mean fill.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill = (bin_capacity - bin_residual) as f64;
    let mean_fill = bin_capacity as f64 - mean_residual;
    if fill > mean_fill {
        score -= 10.0 * (fill - mean_fill) / bin_capacity as f64;
    } else {
        score += 6.0 * (mean_fill - fill) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize opening new bins when open_bins_count is already low relative
    // to progress (few bins, long stream => keep them tight); encourage new
    // bins early when many bins are open and fragmented.
    let new_bin_penalty = 30.0 + 25.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += new_bin_penalty.max(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) with mild nonlinearity.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        if diff < 1.0 {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if nx <= pr {
            // next item fits, but penalize leaving awkward gap after chaining
            score -= 25.0 - 0.4 * diff;
            let chain_gap = pr - nx;
            if chain_gap > 0.0 && chain_gap < 10.0 {
                score -= 8.0; // near-perfect chain
            } else if chain_gap > 30.0 {
                score += 6.0; // leaves another dead space after chain
            }
        } else {
            // next item cannot use the leftover space: penalize proportionally
            score += 0.25 * (nx - pr);
        }
    }

    // Compare post_residual against mean residual across open bins.
    if mean_residual > 0.0 {
        let rel = pr / mean_residual;
        if rel < 0.5 {
            score -= 10.0 * (0.5 - rel); // leaves less waste than average: good
        } else if rel > 1.5 {
            score += 8.0 * (rel - 1.5); // unusually wasteful bin
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation (fill existing bins rather than spreading).
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or when current bins are nearly full of dead space.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let item_f64 = item_size as f64;
        // Opening a new bin is good for large items (they define bin structure well).
        score = 40.0 + 0.6 * (bin_capacity as f64 - item_f64)
            - 50.0 * desperation
            + (step_index as f64 / (total_items.max(1) as f64)) * 5.0;
        // Discourage opening new bins when many bins are already open with slack.
        if mean_residual > item_f64 * 1.5 && fitting_bins_count > 0 {
            score += 25.0;
        }
        // If next item pairs perfectly with this one in a fresh bin, encourage it.
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64 - bin_capacity as f64).abs() < 2.0 {
            score -= 30.0;
        }
    }

    // Progress-based mild tightening: later in stream, be more conservative with waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space hurts more as it approaches mid-range
    let x = post / cap;
    score += 8.0 * x * (1.0 - x) * (1.0 + 2.0 * progress);

    // Reward tight fits strongly (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * tightness * tightness;

    // Lookahead coupling: if next item fits the post residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 * (1.0 - post / cap);
    } else if next_item_size > post_residual {
        score += 2.0 * progress;
    }

    // Last-chance bonus: only one fitting bin -> strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly early, more when many bins open and mean residual is low
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 4.0 + 2.0 * open_pressure + 0.05 * mean_residual + 3.0 * (1.0 - progress);
    } else {
        // Slight preference for bins below mean residual (balance load)
        score += 0.02 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are "perfect fits"
    // (zero or tiny), penalize mid-range dead space, with special treatment of
    // residual classes that are reusable by small items.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 5 {
        score -= 40.0; // near-perfect, negligible waste
    } else if pr <= 15 {
        score -= 18.0; // small, still usable by many item sizes
    } else if pr <= 30 {
        score += 8.0;  // awkward mid-range dead space
    } else if pr <= 50 {
        score += 20.0; // large dead space
    } else {
        score += 32.0; // half-empty bin: wasteful placement
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 align with
    // the discrete item-size grid and are more likely to be filled later.
    if pr % 10 == 0 && pr > 0 {
        score -= 10.0;
    }
    // Residuals congruent to small values mod 10 pair well with typical item tails.
    let r10 = pr % 10;
    if r10 >= 1 && r10 <= 3 {
        score -= 4.0;
    } else if r10 >= 8 {
        score += 3.0;
    }

    // Integer-division thresholds: can the lookahead item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 14.0; // chain placement possible: keep this bin attractive
            // Extra reward when the lookahead exactly consumes the residual class.
            if next_item_size == pr {
                score -= 12.0;
            } else {
                let chained_post = pr - next_item_size;
                if chained_post % 10 == 0 {
                    score -= 6.0;
                }
                if chained_post <= 10 {
                    score -= 5.0;
                }
            }
        } else {
            // Lookahead cannot follow into this bin; mildly penalize so bins that
            // support chaining win ties, unless this is the last-chance bin.
            score += 4.0;
        }
    } else {
        // Last item of the stream: only exact/near-exact closure matters.
        score = pr as f64;
        if pr == 0 {
            score -= 80.0;
        } else if pr <= 10 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer reusing open bins unless the current bin would be
    // badly fragmented. A fresh bin has full residual; make it unattractive when
    // any reasonable fit exists, attractive when the item would strand a bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a bin early when few bins are open (more room to plan),
        // costlier late in the stream when consolidation matters.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        // If many bins fit the item, opening a new one is clearly wasteful.
        if fitting_bins_count >= 2 {
            score += 30.0;
        }
        // If the item is huge relative to capacity, a fresh bin guarantees a clean fit.
        if (item_size as f64) > 0.6 * cap {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: when the fleet of open bins is already spacious,
    // discourage adding more dead space; when residuals are scarce, be lenient.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Mild bonus for packing into bins that are already relatively full
    // (best-fit flavor, scaled by harmonic class of bin_residual).
    let br_class = bin_residual % 20;
    if br_class < 10 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: residuals too small for the smallest item are useless.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Dead-space severity is nonlinear: penalize gaps just below common item sizes.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 20.0 {
        score += (20.0 - gap) * 1.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure to fill existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.3 * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless the fit in open bins is terrible.
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual > 0 && item_size as f64 / bin_capacity as f64 > 0.5 {
            score -= 15.0; // big items justify fresh bins
        }
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mild preference for bins below mean residual (consolidate emptier space).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild bonus scaled by how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit in the leftover: penalize tiny dead space
            // that nothing (sizes >= 1) may use; the smaller the leftover,
            // the worse it is relative to the next item.
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 60.0; // unusably small sliver
            } else {
                score += 0.5 * waste;
            }
        }
    } else {
        // Last item: just prefer tightest fit (post_residual already does that).
    }

    // Compare against mean residual across open bins.
    let cap = bin_capacity as f64;
    let residual_frac = post_residual as f64 / cap;
    let mean_frac = mean_residual / cap;
    // Penalize leaving more residual than the average open bin (fragmentation).
    score += 30.0 * (residual_frac - mean_frac);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: neutral-ish baseline so it wins only when all
    // open fits are poor. Anchor it slightly above a perfect-fit score.
    if bin_residual == bin_capacity {
        score = 40.0 + 0.2 * (open_bins_count as f64);
        // If lookahead shows the item is small and next item is large,
        // opening fresh may still be fine; keep baseline modest.
        if next_item_size > 0 && next_item_size > item_size {
            score += 10.0;
        }
        return score;
    }

    // Prefer fuller bins overall: reward bins whose residual was already low.
    score -= 0.3 * (bin_capacity as f64 - bin_residual as f64) / cap * 10.0;

    // Early in stream: slightly prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: squared residual penalizes large leftover space super-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize creating dead space the next item cannot use.
        score += 4.0;
    }

    // Last-chance urgency: strongly prefer the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding effect: with many open bins, avoid spreading; with few, consolidation matters less.
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score += crowding * 1.5;

    // Time horizon: early in the stream, be more open to spreading (new bins);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Deviation from mean residual: prefer bins whose residual is close to the item
    // (best-fit-like), penalize bins far from the mean to keep residual distribution tight.
    let diff = bin_residual as f64 - item_size as f64;
    score += 0.05 * diff.abs();

    // New-bin candidate handling: baseline attractiveness so a fresh bin is chosen
    // only when existing bins would leave large unusable gaps.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        score = item_size as f64 * 0.9 + 5.0;
        // Open a new bin early when open bins are already fragmented.
        if mean_residual < 25.0 && open_bins_count > 2 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && next_item_size > 50 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fits), non-linearly.
    let mut score = norm_pr.powf(1.5) * cap;

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more -> penalize residual quadratically.
    let coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress);
    score += coupling * cap;

    // Smooth reward for tight fits that still leave room for the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let headroom = (pr - nxt) / cap;
            score -= (1.0 - headroom).powf(2.0) * 8.0 * (1.0 - progress);
        } else {
            // post_residual too small for next item: penalize smoothly by waste fraction
            let waste = (nxt - pr) / nxt;
            score += waste * waste * 12.0;
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // Prefer bins below mean residual mildly (fill emptier bins less aggressively).
    let mr = mean_residual / cap;
    score += (norm_pr - mr).abs().powf(2.0) * 3.0;

    // Slight penalty for opening a new bin when good fits exist.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 8 define "dead space classes".
    // Residues 1..=5 are awkward slivers (hard to fill later); residues 0, 6, 7 are
    // either perfectly closed or still large enough to host small items.
    let residue = post_residual % 8;
    match residue {
        0 => score -= 12.0,                       // perfect closure class
        6 | 7 => score -= 4.0,                    // still serviceable class
        1 | 2 => score += 10.0,                   // worst dead-space classes
        _ => score += 5.0,                        // 3..5: mildly awkward
    }

    // Integer-division thresholds on post_residual: classify remaining space.
    if post_residual == 0 {
        score -= 20.0;                            // exact fit: ideal
    } else if post_residual < 10 {
        score += 15.0;                            // unusable micro-sliver
    } else if post_residual < 20 {
        score += 6.0;
    } else if post_residual >= 50 {
        score -= 6.0;                             // roomy remainder stays flexible
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
            // Bonus if next item lands in the "good residue" class afterward.
            if (post_residual - next_item_size) % 8 == 0 {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this bin's remainder; penalize if remainder is tight.
            if post_residual < next_item_size.min(30) {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented or item
    // is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        if open_bins_count > 0 {
            // Penalize new bins mildly, more when item is small.
            score += 14.0 + (100 - item_size.min(100)) as f64 * 0.15
                   - fragmentation * 0.05
                   - progress * 5.0;
        } else {
            score -= 30.0; // must open the first bin
        }
    }

    // Slight preference for tighter existing bins overall.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance: unusable small gaps are heavily penalized ---
    if post_residual > 0 {
        if post_residual <= 10 {
            // Dead space: nothing in [1,100] range reliably fits; punish hard.
            score += 60.0 * (11.0 - post_residual as f64);
        } else if post_residual < 20 {
            // Risky zone: only tiny items fit; moderate penalty.
            score += 15.0 * (20.0 - post_residual as f64) / 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // --- Reward tight fits (small post_residual relative to item size) ---
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // --- Open-bin pressure: discourage spreading across many bins unless fit is good ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (open_bins_count as f64) * (1.0 - 0.5 * progress);

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- Lookahead: if the next item fits exactly in post_residual, big reward ---
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        score -= 8.0;
    }

    // --- New-bin candidate: only attractive when no open bin offers a decent fit ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // More attractive when the current bin would leave a bad gap.
        if post_residual > 0 && post_residual < 20 {
            score -= 35.0;
        }
        // Attractive if next item is large and would waste the bin anyway.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 20.0;
        }
        // Discourage opening new bins when many bins are already open with slack.
        if mean_residual > (bin_capacity as f64) * 0.5 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

