    // 2-step lookahead: reward when post_residual exactly matches next item,
    // penalize when post_residual is just barely too small for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
