            // when the gap is small (near-miss is wasteful)
            let gap = (next_item_size - post_residual) as f64;
            score += 30.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor),
    // but discourage leaving residual far below mean (fragmentation).
    let dev = post_residual as f64 - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // New-bin candidate: make empty bins attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score = 120.0 + 0.3 * mean_residual;
    }

    // Late in the stream, prefer closing out bins (reduce open-bin sprawl).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64 - 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable slivers (< 10% of capacity) — dead space.
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid wasting an almost-full bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Extra reward if post-residual matches next item exactly-ish.
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only make it
    // attractive when existing bins fit poorly (large waste) or none fit well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 18.0 + 30.0 * progress;
        // If many open bins with slack exist, discourage opening another.
        if open_bins_count > 0 {
            new_bin_cost += 4.0 * open_bins_count as f64;
            // But if mean residual is small (bins nearly full), new bin is fine.
            new_bin_cost -= 0.5 * mean_residual;
        }
        // If the next item is large, having fresh capacity helps.
        if next_item_size >= bin_capacity / 2 {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost.max(0.0);
    } else {
        // Mild penalty when this open bin's residual far exceeds the item
        // (wasting a big bin on a small item), scaled by global slack.
        let waste = (bin_residual - item_size) as f64;
        score += 0.05 * waste * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
