    score += (prn * prn * prn) * (t * 40.0 + 10.0);
    // Reward tight fits (small post residual) via smooth negative term
    score -= (1.0 - prn) * (1.0 - prn) * 15.0;
    // Lookahead: penalize if post residual can't fit next item
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 8.0 + 0.05 * (next_item_size as f64 - pr);
    } else if next_item_size > 0 {
        score -= 4.0 * (1.0 - ((next_item_size as f64 - pr).abs() / cap));
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }
    // Discourage opening new bins when good fits exist among many open bins
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (open_bins_count as f64).sqrt() + mean_residual * 0.05;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins whose post-residual falls
    // into "usable" classes (multiples of common item sizes) are rewarded.
    let pr = post_residual;
    // Reward residuals that are exactly reusable by the lookahead item.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 25.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Lookahead cannot use this bin's remainder -> penalize dead space.
        score += 12.0;
    }

    // Perfect fit bonus (waste-free placement).
    if pr == 0 {
        score -= 60.0;
    }

    // Modulo classes: residuals divisible by small common sizes stay flexible.
    if pr > 0 {
        let mut flex = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                flex += 6.0;
            }
        }
        score -= flex * (pr as f64 / cap);
    }

    // Penalize tiny unusable slivers (1..10) — dead space.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Integer-division threshold: residual in [item, item+9] band is a near fit.
    let q = pr / 10;
    let band_bonus = match q {
        0 => 8.0,
        1 => 4.0,
        2 => 0.0,
        _ => -2.0,
    };
    score += band_bonus;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when it serves large items or stream end.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 > 0.7 * cap;
        if big_item {
            score -= 30.0;
        } else if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= cap {
            score += 10.0; // pair fits elsewhere, discourage new bin
        }
        if progress > 0.9 {
            score += 5.0 * progress;
        }
        // Empty bin has no dead-space risk; mild tie-breaker by mean residual.
        score += mean_residual / cap * 3.0;
    }

    // Encourage tight packing relative to current mean residual.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
