        } else if second <= 8 {
            score -= 7.0;
        } else if second < 25 {
            score += 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead-space ratio penalty: leftover too small for next item.
        let gap_frac = post_residual as f64 / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Mild preference for bins below mean residual (consolidate emptier space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= (mean_residual - bin_residual as f64) * 0.05;
    score += 0.08 * dev;

    // Residual-efficiency steering: concentrate slack in fewer bins.
    let slack = bin_residual as f64 - item_size as f64;
    if slack > mean_residual {
        score += 0.06 * (slack - mean_residual);
    } else {
        score -= 0.06 * (mean_residual - slack);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let horizon_cost = 40.0 * (0.25 + progress * progress);
        let waste_vs_mean = (cap - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        } else if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        score += 12.0 * pressure;
        // Fresh bin hosting current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Big items justify fresh bins, especially when packing is tight.
        if mean_residual / cap < 0.25 && (item_size as f64) > 0.5 * cap {
            score -= 10.0;
        }
        if (item_size as f64) < 0.4 * cap {
            score += 10.0;
        }
        if progress < 0.2 && item_size as f64 > 0.6 * cap {
            score -= 8.0;
        }
    } else {
        // Late stream: reward finishing bins off.
        if progress > 0.7 && post_residual <= 20 {
            score -= 12.0 * progress;
        }
