        // next item's size (or within a tiny tolerance), the bin closes
        // cleanly next step; this is the strongest anti-dead-space signal.
        if next_item_size > 0 && post_residual >= next_item_size {
            let diff = post_residual - next_item_size;
            if diff <= 2 {
                score -= 8.0;
            }
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

