    // reusable by a plausible upcoming item (near mean residual within a
    // small tolerance), this bin's dead space will likely be consumed.
    if post_residual > 0 && mean_residual > 0.0 {
        let m = mean_residual;
        if (post_residual as f64 - m).abs() <= 3.0 {
