    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Reward near-perfect fits (nonlinear, capacity-normalized).
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 18.0 * tight * tight;
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space severity is nonlinear: penalize gaps just below common item sizes.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 20.0 {
        score += (20.0 - gap) * 1.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure to fill existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() / (1.0 + cap).ln();
    score += (open_bins_count as f64) * 0.3 * (0.5 + progress);
    score -= 10.0 * pressure * tight;

    // New-bin candidate: strongly penalize opening a new bin unless justified.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + progress * progress);
        score = 100.0 + horizon_cost;
        // big items justify fresh bins, especially early
        if item_size as f64 / cap > 0.5 {
            score -= 18.0;
        }
        // fresh bin can host current + next item together
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 10.0;
            }
        }
        // small items should not seed fresh bins
        if (item_size as f64) < 0.4 * cap {
            score += 12.0;
        }
        // escalate with number of competing open bins
        if fitting_bins_count >= 2 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 2.0);
        } else if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // late stream: opening new bins is very costly
        if progress > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (progress - 0.5);
        }
        // early stream with large item: fresh bin has runway
        if progress < 0.2 && item_size as f64 > 0.6 * cap {
            score -= 8.0;
        }
    }

    // Lookahead: favor bins whose leftover can host the next item (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 20.0 * chain_fit;
        let second = post_residual - next_item_size;
        if second == 0 {
            score -= 14.0;
        } else if second <= 8 {
            score -= 7.0;
        } else if second < 25 {
            score += 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // gap too small for next item: penalize by closeness
        let gap_frac = post_residual as f64 / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Awkward-middle band penalty: gaps too large to ignore, too small to rely on.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / cap;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / cap;
            score += 8.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
        // residuals near mean residual are likely fillable by upcoming items
        if mean_residual > 0.0 {
            let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
            score += 4.0 * rel.min(2.0);
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier space).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // Late stream: reward closing bins out.
    if !is_new_bin {
        if progress > 0.7 && post_residual <= 20 {
            score -= 12.0 * progress;
        }
        if progress > 0.7 && next_item_size > 0 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        if progress > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Mild deterministic tie-breaker.
    score += (bin_residual as f64) * 0.01;

    score
}

