        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        // Scale opening reluctance with global bin pressure.
        score += 12.0 * pressure;
        // Lookahead synergy: fresh bin can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
