            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Opening is worse late in the stream when existing open bins
        // still have ample slack relative to the item.
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        // If the best existing alternative would leave a large awkward
        // gap, opening a fresh bin becomes relatively more attractive.
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // NEW: triple-fit lookahead — a fresh bin that can host the current
        // item plus the next two typical items (approximated by mean
        // residual) is a strong consolidation seed; reward it.
        if next_item_size > 0 && mean_residual > 0.0 {
            let third = item_size as f64 + next_item_size as f64 + mean_residual;
            if third <= bin_capacity as f64 {
                score -= 6.0;
            }
        }
        // NEW: mid-stream fresh-bin seeding is only worth it for large items;
        // small items mid-stream should almost always go into open bins.
