                let closeness = 1.0 - ((after as f64 - mean_residual) / bin_capacity as f64);
                score -= 5.0 * closeness;
            } else if after > 0 && (after as f64) < mean_residual * 0.4 {
                score += 3.0; // leaves an awkward sub-typical gap after the chain
            }
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

