    // mid-range awkward gaps are penalized slightly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_residual = post_residual - next_item_size;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // Dead-space ratio targeting — penalize "awkward middle" post-residuals:
    // too large to discard, too small to reliably host future items.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    // Usability-weighted residual — reward post-residuals that sit close to
    // the mean residual (likely to be filled by an upcoming item).
    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
    }

    // Scarcity-weighted consolidation — when only a couple of bins can
    // host the item, closing them down cleanly matters more.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Dead-space waste metric — post-residual measured against the
    // largest plausible future filler (next item). A gap the next item
    // cannot use but that is a substantial fraction of capacity is the
    // dominant source of wasted bins; penalize it proportionally.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * unusable_frac;
    }

    // NEW: divisibility-aware dead space — a residual that is an exact
    // multiple of small item sizes (1..=4) is far more likely to be
    // filled later than an arbitrary gap; reward such "rescuable" gaps.
    if post_residual > 0 {
        let mut rescuable = false;
        for s in 1..=4u32 {
            if post_residual % s == 0 && post_residual / s <= 8 {
                rescuable = true;
                break;
            }
        }
        if rescuable {
            score -= 5.0;
        }
    }

    // Dynamic time horizon: late in the stream, avoid opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        // Opening is acceptable when few fitting bins exist.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        // Scale opening reluctance with global bin pressure.
        score += 12.0 * pressure;
        // Lookahead synergy: fresh bin can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Opening is more attractive when the fresh bin would host the
        // current item plus a large share of typical future items.
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Penalize opening a new bin when the current item is small relative
        // to capacity (wasteful seeding of a fresh bin).
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        // Opening a fresh bin is more tolerable early in the stream.
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        // With several competing open bins, opening is almost always
        // wasteful — escalate the penalty with fitting_bins_count.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Opening is worse late in the stream when existing open bins
        // still have ample slack relative to the item.
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        // A fresh tight start can pay off when mean residual is large
        // (loose packing so far) and the item is big.
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // If the item nearly fills the fresh bin entirely, opening is
        // essentially free — the residual waste is minimal.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW: triple lookahead — opening is notably better when the fresh
        // bin can absorb the current item, the next item, and still leave a
        // gap matching the mean residual (likely to be filled later).
        if next_item_size > 0 && mean_residual > 0.0 {
            let triple_slack = bin_capacity as f64 - item_size as f64 - next_item_size as f64;
            if triple_slack >= 0.0 && (triple_slack - mean_residual).abs() < 5.0 {
                score -= 9.0;
            }
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        // Mid-stream, mildly favor bins whose post-residual matches the next
        // item (probable chain), reducing fragmentation.
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Late-stream strong finishing bonus — residual below next item
        // size means this bin is essentially closed; reward closing early.
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        // Fragmentation guard — mid/late stream, prefer bins whose
        // post-residual remains large enough to be reusable by typical items.
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering — among open bins, mildly favor
        // the emptiest usable bins so that nearly-full bins close out and
        // slack concentrates in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // Late-stream exact-chain boost — near the end, a placement that
        // lets the next item land perfectly is worth extra.
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        // Consolidation depth bonus — when several bins fit the item,
        // prefer the one whose remaining residual best matches the mean
        // residual (future items are statistically most likely to land
        // there), weighted by how many alternatives exist.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: near-closure sweep — when the placement leaves a residual so
        // small that only tiny items could use it, treat the bin as closed
        // and reward it proportionally to how close it is to zero, scaled
        // by global pressure (more open bins -> closing matters more).
        if post_residual > 0 && post_residual <= 6 {
            score -= 4.0 * (1.0 - post_residual as f64 / 6.0) * (1.0 + pressure);
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: residuals too small for the smallest item are useless.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Reward near-perfect fits with escalating bonuses.
    if post_residual == 0 {
        score -= 55.0;
    } else if post_residual <= 3 {
        score -= 28.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    }

    // Dead-space severity is nonlinear: penalize gaps just below common item sizes.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 20.0 {
        score += (20.0 - gap) * 1.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure to fill existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score += (open_bins_count as f64) * 0.3 * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless the fit in open bins is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    let fill_frac = item_size as f64 / bin_capacity as f64;
    if is_new_bin {
        // Base opening cost rises with stream progress (late openings waste more).
        let mut open_score = 90.0 + 45.0 * progress * progress;
        // Big items justify fresh bins; near-full items make opening nearly free.
        if fill_frac > 0.5 {
            open_score -= 15.0;
        }
        if fill_frac > 0.9 {
            open_score -= 20.0 * (fill_frac - 0.9);
        }
        if fill_frac < 0.4 {
            open_score += 12.0;
        }
        // Few fitting bins -> opening is acceptable.
        if fitting_bins_count == 0 {
            open_score -= 40.0;
        } else if fitting_bins_count == 1 {
            open_score -= 20.0;
        } else {
            open_score += 6.0 + 3.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Global bin pressure discourages opening.
        open_score += 15.0 * pressure;
        // Fresh bin synergy: can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            open_score -= 14.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                open_score -= 10.0;
            }
        }
        // If mean residual is large (loose packing), a fresh tight start helps.
        let mean_frac = mean_residual / bin_capacity as f64;
        if mean_frac > 0.35 && fill_frac > 0.7 {
            open_score -= 8.0 * (mean_frac - 0.35);
        }
        score = open_score;
    } else {
        // Scarcity-weighted consolidation: with few fitting bins, use the best one.
        if fitting_bins_count >= 1 && post_residual > 0 {
            let scarcity = 1.0 / fitting_bins_count as f64;
            let tight = 1.0 - post_residual as f64 / bin_capacity as f64;
            score -= 7.0 * scarcity * tight;
        }

        // Lookahead: favor bins whose leftover can host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 9.0;
            let second_residual = post_residual - next_item_size;
            if second_residual == 0 {
                score -= 14.0;
            } else if second_residual <= 8 {
                score -= 6.0;
            } else if second_residual < 25 {
                score += 3.0;
            }
        } else if next_item_size > 0 && post_residual > 0 {
            // Unusable-by-next-item gap is the dominant waste source.
            let unusable_frac = post_residual as f64 / bin_capacity as f64;
            score += 12.0 * unusable_frac;
        }

        // Late stream: reward closing bins out.
        if progress > 0.7 && post_residual <= 20 {
            score -= 12.0 * progress;
        }
        if progress > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * progress;
        }

        // Awkward-middle gap penalty: too large to ignore, too small to reuse.
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if post_residual > 0 && gap_ratio > 0.05 && gap_ratio < 0.30 {
            score += 8.0 * gap_ratio;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier space).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // Deterministic tie-breaker on residual ordering.
    score += bin_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

