    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize creating dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 24.0 * chain_fit;
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }
    if next_item_size > post_residual && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score -= 10.0 * pressure * tight;

    // Mean residual coupling: deviating bins get a nudge toward use if they fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Dead-space-aware nudge — prefer bins whose post-residual is small
    // relative to the mean residual (less fragmentation overall).
    let post_frac = post_residual as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    if post_frac < mean_frac {
        score -= 5.0 * (mean_frac - post_frac);
    } else {
        score += 3.0 * (post_frac - mean_frac);
    }

    // Dead-space ratio penalty — post-residual that is too small for the
    // next item but too large to ignore represents wasted space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap_frac = post_residual as f64 / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Two-step lookahead — estimate the residual after hypothetically
    // placing the next item too.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_residual = post_residual - next_item_size;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 8.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // Dead-space ratio targeting — penalize "awkward middle" post-residuals.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    // Usability-weighted residual — reward post-residuals close to mean residual.
    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
    }

    // Scarcity-weighted consolidation.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Dead-space waste metric — post-residual measured against the largest
    // plausible future filler (next item).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_residual as f64 / bin_capacity as f64;
        score += 15.0 * unusable_frac;
    }

    // NEW: residual reusability — post-residuals that are >= the minimum
    // plausible item size (small items exist) stay usable; scale the
    // awkward-middle penalty by how far below the mean residual the gap sits.
    if post_residual > 0 && mean_residual > 0.0 {
        let reuse = post_residual as f64 / (mean_residual + 1.0);
        if reuse < 0.5 {
            score += 3.0 * (0.5 - reuse);
        }
    }

    // Dynamic time horizon: late in the stream, avoid opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        score += 12.0 * pressure;
        // Lookahead synergy: fresh bin can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            } else if pair_slack <= 20 {
                score -= 5.0;
            }
        }
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // Nearly-filling a fresh bin makes opening essentially free.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 22.0 * (fill_frac - 0.9);
        }
        // NEW: opening is also acceptable when the fresh bin's leftover
        // (capacity - item) is small relative to the mean residual — it will
        // likely be consumed by the next typical item.
        let fresh_left = bin_capacity - item_size;
        if fresh_left > 0 && mean_residual > 0.0 && (fresh_left as f64) <= mean_residual * 1.2 {
            score -= 10.0;
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering — concentrate slack in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        // Consolidation depth bonus — prefer bins whose post-residual best
        // matches the mean residual, weighted by alternatives.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: near-closure bonus — if placing here leaves a residual that
        // no item of at least size 1 can meaningfully chain into (i.e. the
        // bin is nearly full), reward closing it out, scaled by stream time.
        if post_residual > 0 && post_residual <= 2 {
            score -= 8.0 * (0.5 + t);
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

