        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Two-step lookahead — estimate the residual after hypothetically
    // placing the next item too. Perfect chain-closure is rewarded hard;
    // mid-range awkward gaps are penalized slightly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_residual = post_residual - next_item_size;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // Dead-space ratio targeting — penalize "awkward middle" post-residuals:
    // too large to discard, too small to reliably host future items.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    // Usability-weighted residual — reward post-residuals that sit close to
    // the mean residual (likely to be filled by an upcoming item).
    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
    }

    // Scarcity-weighted consolidation — when only a couple of bins can
    // host the item, closing them down cleanly matters more.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Dead-space waste metric — post-residual measured against the
    // largest plausible future filler (next item). A gap the next item
    // cannot use but that is a substantial fraction of capacity is the
    // dominant source of wasted bins; penalize it proportionally.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * unusable_frac;
    }

    // NEW (gen 7): waste-to-go metric — measure the dead space not against
    // only the next item but against the mean residual of the stream. A
    // post-residual below the mean residual is statistically unlikely to
    // ever be filled; weight that stranded fraction by stream progress so
    // the penalty grows as fewer chances remain to fill it.
    if post_residual > 0 && mean_residual > 1.0 && (post_residual as f64) < mean_residual {
        let t0 = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let stranded = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score += 10.0 * stranded * (0.4 + 0.6 * t0);
    }

    // Dynamic time horizon: late in the stream, avoid opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
