            } else if post_residual as f64 > 2.0 * mean_residual && t > 0.5 {
                // Hoarding slack late in the stream is wasteful; nudge
                // toward bins that consume more of their residual now.
                score += 3.0 * (post_residual as f64 / bin_capacity as f64);
            }
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

