            score -= 35.0;
        }
        // Loose packing so far + big item -> fresh tight start can pay off.
        if mean_frac > 0.35 && fill_frac > 0.7 {
            score -= 10.0 * (mean_frac - 0.35);
        }
        // Small items seeding fresh bins are wasteful.
        if fill_frac < 0.4 {
            score += 12.0;
        }
        // Late stream: opening new bins is worse.
        if progress > 0.5 {
            score += 15.0 * (progress - 0.5);
        }
    } else {
        // Lookahead: favor bins whose leftover can host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
