    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space severity is nonlinear: penalize gaps just below common item sizes.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 20.0 {
        score += (20.0 - gap) * 1.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Scarcity-weighted consolidation: with few fitting bins, tight fits matter more.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Pressure to fill existing bins when many are open (log-scaled).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score += (open_bins_count as f64) * 0.3 * (0.5 + progress);
    score -= 10.0 * pressure * (1.0 - gap / bin_capacity as f64).max(0.0);

    // Tightness quadratic reward (strong pull toward best fits).
    let tight = 1.0 - (gap / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
