        // below the next item — that dead space can never be recovered.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual > next_item_size / 2 {
            score += 6.0 * t;
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

