    if next_item_size > post_residual && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score -= 10.0 * pressure * tight;

    // Mean residual coupling: deviating bins get a nudge toward use if they fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Dead-space-aware nudge — prefer bins whose post-residual is small
    // relative to the mean residual (less fragmentation overall).
    let post_frac = post_residual as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    if post_frac < mean_frac {
        score -= 5.0 * (mean_frac - post_frac);
    } else {
        score += 3.0 * (post_frac - mean_frac);
    }

    // Dead-space ratio penalty — post-residual that is too small for the
    // next item but too large to ignore represents wasted space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap_frac = post_residual as f64 / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Two-step lookahead — estimate the residual after hypothetically
    // placing the next item too.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_residual = post_residual - next_item_size;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // Dead-space ratio targeting — penalize "awkward middle" post-residuals.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    // Usability-weighted residual — reward post-residuals that sit close to
    // the mean residual (likely to be filled by an upcoming item).
    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
    }

    // Scarcity-weighted consolidation.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // NEW: dead-space waste metric — post-residual measured against the
    // largest plausible future filler (next item).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * unusable_frac;
    }

    // NEW: exact-halving detection — a post-residual that can host the next
    // item AND then still host a typical item after that is a premium chain.
    if next_item_size > 0 && post_residual >= next_item_size && mean_residual > 0.0 {
        let after_next = post_residual - next_item_size;
        if (after_next as f64) >= mean_residual {
            score -= 4.0;
        }
    }

    // Dynamic time horizon: late in the stream, avoid opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        // Opening is acceptable when few fitting bins exist.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        // Scale opening reluctance with global bin pressure.
        score += 12.0 * pressure;
        // Lookahead synergy: fresh bin can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Opening is more attractive when the fresh bin would host the
        // current item plus a large share of typical future items.
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Penalize opening a new bin when the current item is small.
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        // Opening a fresh bin is more tolerable early in the stream.
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        // With several competing open bins, opening is almost always wasteful.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Opening is worse late in the stream when existing open bins
        // still have ample slack relative to the item.
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        // A fresh tight start can pay off when mean residual is large.
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // If the item nearly fills the fresh bin entirely, opening is free.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW: opening is cheaper when existing bins' slack is systematically
        // too small for the item (they can't help anyway).
        let min_usable_slack = (bin_capacity as f64 - mean_residual).max(1.0);
        if (item_size as f64) > min_usable_slack && fitting_bins_count >= 2 {
            score -= 6.0;
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        // Mid-stream, mildly favor bins whose post-residual matches the next item.
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Late-stream strong finishing bonus.
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        // Fragmentation guard — mid/late stream.
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering — concentrate slack in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // Late-stream exact-chain boost.
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        // Consolidation depth bonus.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: waste-closure bonus — when this placement leaves a residual
        // smaller than the smallest plausible future item (approximated by
        // mean residual/2), the bin is effectively sealed; reward sealing
        // bins early rather than letting them linger as dead space.
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
            score -= 5.0 * (1.0 - t);
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: residuals too small for the smallest item are useless.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Reward near-perfect fits with escalating rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead-space severity is nonlinear: penalize gaps just below common item sizes.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 20.0 {
        score += (20.0 - gap) * 1.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Scarcity-weighted consolidation: with few fitting bins, tight fits matter more.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Pressure to fill existing bins when many are open (log-scaled).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score += (open_bins_count as f64) * 0.3 * (0.5 + progress);
    score -= 10.0 * pressure * (1.0 - gap / bin_capacity as f64).max(0.0);

    // Tightness quadratic reward (strong pull toward best fits).
    let tight = 1.0 - (gap / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // New-bin candidate: penalize opening a new bin unless the fit in open bins is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 25.0;
        if fill_frac > 0.5 {
            score -= 15.0;
        }
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        if fill_frac < 0.4 {
            score += 10.0;
        }
        // Fresh bin synergy: current + next item pair well together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Escalate penalty with competing open bins.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Late stream: opening new bins is worse.
        score += 30.0 * progress * progress;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Global bin pressure discourages opening.
        score += 12.0 * pressure;
        // Late stream with alternatives: extra reluctance.
        if progress > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (progress - 0.5);
        }
        // Big item early: fresh bin acceptable.
        if progress < 0.2 && fill_frac > 0.6 {
            score -= 8.0;
        }
        // NEW: opening is wasteful when the current item is small relative to capacity.
        if fill_frac < 0.35 {
            score += 8.0;
        }
        // NEW: opening is cheap if the item nearly fills the fresh bin entirely.
        if fill_frac > 0.95 {
            score -= 25.0;
        }
    }

    // Lookahead: favor bins whose leftover can host the next item, with chain-closure bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let second_residual = post_residual - next_item_size;
        let chain_fit = 1.0 - (second_residual as f64 / bin_capacity as f64);
        score -= 22.0 * chain_fit;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
        // Late-stream exact-chain boost.
        if progress > 0.6 && second_residual == 0 {
            score -= 8.0 * progress;
        }
        // NEW: two-step lookahead — a chain that leaves a gap the *next-next*
        // typical item (approximated by mean residual) could use is worth more.
        if second_residual > 0 && mean_residual > 0.0 && (second_residual as f64) >= mean_residual {
            score -= 3.0;
        } else if second_residual > 0 && mean_residual > 0.0 && (second_residual as f64) < mean_residual * 0.5 {
            score += 2.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
        // Unusable-gap penalty scaled by capacity fraction.
        score += 14.0 * (gap / bin_capacity as f64);
        // Gap-relative penalty: gap barely below next item is worst.
        let gap_frac = gap / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Mild preference for bins below mean residual (consolidate emptier space).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // Residual-efficiency steering: concentrate slack in fewer bins.
    if !is_new_bin {
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // Late-stream finishing bonus: close bins out early.
        if progress > 0.7 && post_residual <= 20 {
            score -= 12.0 * progress;
        }
        if progress > 0.7 && next_item_size > 0 && post_residual < next_item_size {
            score -= 6.0;
        }
        // Fragmentation guard mid/late stream.
        if progress > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - progress);
        }
        // Consolidation depth bonus: prefer residual matching the mean when alternatives exist.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // Awkward-middle gap penalty: too large to discard, too small to reliably reuse.
        if post_residual > 0 {
            let gap_ratio = gap / bin_capacity as f64;
            if gap_ratio > 0.05 && gap_ratio < 0.30 {
                let mean_gap_dist = (gap - mean_residual).abs() / bin_capacity as f64;
                score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
            }
        }
        // NEW: mid-stream chain seeding — when the next item exactly closes this
        // bin, prefer it even more strongly with multiple alternatives present.
        if progress > 0.3 && next_item_size > 0 && post_residual == next_item_size && fitting_bins_count >= 2 {
            score -= 5.0;
        }
        // NEW: penalize leaving a residual that is unusable by the mean-sized
        // upcoming item but too large to ignore — the dominant waste source.
        if post_residual > 0 && mean_residual > 0.0 && (post_residual as f64) < mean_residual {
            let unusable = 1.0 - (post_residual as f64 / mean_residual);
            score += 4.0 * unusable * (0.5 + progress);
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

