            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: near-closure sweep — when the post-residual is within a small
        // epsilon of zero but nonzero, treat it as a near-perfect fill and
        // reward it proportionally so slivers of dead space get squeezed out.
        if post_residual > 0 && post_residual <= 2 {
            score -= 10.0 - 3.0 * (post_residual as f64);
        }
