    // matters; when many bins are open, small unusable gaps compound.
    // Penalize leaving a small unusable gap harder when open_bins_count
    // is high (fragmentation compounding), reward closing bins out.
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        let compound = (open_bins_count as f64).sqrt() / 10.0;
        score += 6.0 * compound;
    }

    // Dynamic time horizon: late in the stream, avoid opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        // Opening is acceptable when few fitting bins exist.
