        // essentially free — the residual waste is minimal.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW: opening is justified when the fresh bin's post-residual
        // would be a "good" residual — large enough to host typical
        // upcoming items (close to or above mean residual). This avoids
        // seeding bins that strand tiny unusable slivers.
        if next_item_size > 0 && item_size < bin_capacity {
            let fresh_post = bin_capacity - item_size;
            if fresh_post >= next_item_size && fresh_post as f64 >= 0.5 * mean_residual.max(1.0) {
                score -= 6.0 + 4.0 * (fresh_post as f64 / bin_capacity as f64);
            }
            // Conversely, a fresh bin stranding a tiny sliver is bad.
            if fresh_post > 0 && fresh_post < next_item_size {
                score += 8.0;
            }
        }
        // NEW: when open bins collectively have plenty of slack (mean
        // residual large), opening is clearly wasteful.
        if mean_frac > 0.3 {
            score += 10.0 * (mean_frac - 0.3);
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        // Mid-stream, mildly favor bins whose post-residual matches the next
        // item (probable chain), reducing fragmentation.
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Late-stream strong finishing bonus — residual below next item
        // size means this bin is essentially closed; reward closing early.
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        // Fragmentation guard — mid/late stream, prefer bins whose
        // post-residual remains large enough to be reusable by typical items.
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering — among open bins, mildly favor
        // the emptiest usable bins so that nearly-full bins close out and
        // slack concentrates in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // Late-stream exact-chain boost — near the end, a placement that
        // lets the next item land perfectly is worth extra.
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        // Consolidation depth bonus — when several bins fit the item,
        // prefer the one whose remaining residual best matches the mean
        // residual (future items are statistically most likely to land
        // there), weighted by how many alternatives exist.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: residual usability horizon — a post-residual that can host
        // the next item AND leaves a second usable gap is far better than
        // one that hosts it and strands nothing useful. Reward leaving a
        // second_residual close to typical item sizes; penalize stranding
        // a second_residual that is too small for anything.
        if next_item_size > 0 && next_item_size <= post_residual {
            let second_residual = post_residual - next_item_size;
            if second_residual > 0 {
                if second_residual >= next_item_size {
                    score -= 4.0; // chainable again — good.
                } else if second_residual < 6 {
                    score += 4.0 * (1.0 - second_residual as f64 / 6.0); // stranded sliver.
                }
            }
        }
        // NEW: best-fit escalation under scarcity — when exactly two bins
        // fit, the tighter fit should win decisively to avoid splitting
        // slack across both bins.
        if fitting_bins_count == 2 {
            score -= 10.0 * tight * tight;
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

