        if fill_frac < 0.4 {
            score += 5.0;
        }
        // NEW: when the current bin's post-residual would be zero anyway
        // (item fits an open bin perfectly), opening is pure waste.
        if fitting_bins_count >= 1 && fill_frac > 0.95 {
            score -= 10.0;
        }
    }

