        // Consolidation depth bonus: prefer residual matching the mean when alternatives exist.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
