        if next_item_size > 0 && post_residual >= next_item_size {
            let second = post_residual - next_item_size;
            if second >= 1 && second <= 30 && second >= next_item_size / 2 {
                score -= 3.0;
            }
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

