            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW (gen 9): triple lookahead — if the next item would leave a
        // residual that itself fits the mean item size, this bin supports
        // a 3-item chain; reward it proportionally to stream progress.
        if next_item_size > 0 && next_item_size <= post_residual {
            let second_residual = post_residual - next_item_size;
            let third_ok = (second_residual as f64) >= mean_residual * 0.9
                && (second_residual as f64) <= mean_residual * 1.1;
            if third_ok {
                score -= 6.0 * (0.5 + t);
            }
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: residuals too small for the smallest item are useless.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Reward near-perfect fits with escalating rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space severity is nonlinear: penalize gaps just below common item sizes.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 20.0 {
        score += (20.0 - gap) * 1.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Scarcity-weighted consolidation: with few fitting bins, tight fits matter more.
    let tight = 1.0 - (gap / bin_capacity as f64);
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Pressure to fill existing bins when many are open (log-scaled).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score += (open_bins_count as f64) * 0.3 * (0.5 + progress);
    score -= 10.0 * pressure * tight.max(0.0);

    // Tightness quadratic reward: strong pull toward best fits.
    score -= 18.0 * tight * tight;

    // Dead-space waste metric: gap the next item cannot use is wasted space.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0 * (gap / bin_capacity as f64);
        let gap_frac = gap / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // New-bin candidate block.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 25.0;
        if fill_frac > 0.5 {
            score -= 15.0;
        }
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        if fill_frac < 0.4 {
            score += 10.0;
        }
        // Fresh bin synergy: current + next item pair well together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Escalate penalty with competing open bins.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Late stream: opening new bins is worse.
        score += 30.0 * progress * progress;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        // Global bin pressure discourages opening.
        score += 12.0 * pressure;
        // Late stream with alternatives: extra reluctance.
        if progress > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (progress - 0.5);
        }
        // Big item early: fresh bin acceptable.
        if progress < 0.2 && fill_frac > 0.6 {
            score -= 8.0;
        }
        // Fresh tight start pays off when mean residual is large and the item is big.
        let mean_frac = mean_residual / bin_capacity as f64;
        if mean_frac > 0.35 && fill_frac > 0.7 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // Small item seeding a fresh bin is wasteful.
        if fill_frac < 0.4 {
            score += 5.0;
        }
        // Opening is more attractive when packing has been loose and the item is large.
        if mean_frac < 0.25 && fill_frac > 0.5 {
            score -= 10.0;
        }
    }

    // Lookahead: favor bins whose leftover can host the next item, with chain-closure bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let second_residual = post_residual - next_item_size;
        let chain_fit = 1.0 - (second_residual as f64 / bin_capacity as f64);
        score -= 22.0 * chain_fit;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
        // Late-stream exact-chain boost.
        if progress > 0.6 && second_residual == 0 {
            score -= 8.0 * progress;
        }
        // Mid-stream chain probability bonus.
        if progress > 0.3 && progress <= 0.7 {
            score -= 4.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier space).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // Residual-efficiency steering: concentrate slack in fewer bins.
    if !is_new_bin {
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // Late-stream finishing bonus: close bins out early.
        if progress > 0.7 && post_residual <= 20 {
            score -= 12.0 * progress;
        }
        if progress > 0.7 && next_item_size > 0 && post_residual < next_item_size {
            score -= 6.0;
        }
        // Fragmentation guard mid/late stream.
        if progress > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - progress);
        }
        // Consolidation depth bonus: prefer residual matching the mean when alternatives exist.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // Usability-weighted residual — penalize post-residuals far from the mean residual.
        if post_residual > 0 && mean_residual > 0.0 {
            let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
            score += 4.0 * rel.min(2.0);
        }
        // Awkward-middle gap penalty: too large to discard, too small to reliably reuse.
        if post_residual > 0 {
            let gap_ratio = gap / bin_capacity as f64;
            if gap_ratio > 0.05 && gap_ratio < 0.30 {
                let mean_gap_dist = (gap - mean_residual).abs() / bin_capacity as f64;
                score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
            }
        }
        // NEW: post-residual vs mean-frac steering — reward bins whose leftover is
        // tighter than the average leftover (less fragmentation overall).
        let post_frac = gap / bin_capacity as f64;
        if post_frac < mean_frac {
            score -= 5.0 * (mean_frac - post_frac);
        } else {
            score += 3.0 * (post_frac - mean_frac);
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
