        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize creating dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 22.0 * chain_fit;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }
    if next_item_size > post_residual && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score -= 10.0 * pressure * tight;

    // Mean residual coupling: deviating bins get a nudge toward use if they fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Dead-space-aware nudge — prefer bins whose post-residual is small
    // relative to the mean residual (less fragmentation overall).
    let post_frac = post_residual as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    if post_frac < mean_frac {
        score -= 5.0 * (mean_frac - post_frac);
    } else {
        score += 3.0 * (post_frac - mean_frac);
    }

    // Dead-space ratio penalty — post-residual that is too small for the
    // next item but too large to ignore represents wasted space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap_frac = post_residual as f64 / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Two-step lookahead — estimate the residual after hypothetically
    // placing the next item too. Perfect chain-closure is rewarded hard;
    // mid-range awkward gaps are penalized slightly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_residual = post_residual - next_item_size;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // Dead-space ratio targeting — penalize "awkward middle" post-residuals:
    // too large to discard, too small to reliably host future items.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    // Usability-weighted residual — reward post-residuals that sit close to
    // the mean residual (likely to be filled by an upcoming item).
    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
    }

    // Scarcity-weighted consolidation — when only a couple of bins can
    // host the item, closing them down cleanly matters more.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Dead-space waste metric — post-residual measured against the
    // largest plausible future filler (next item). A gap the next item
    // cannot use but that is a substantial fraction of capacity is the
    // dominant source of wasted bins; penalize it proportionally.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * unusable_frac;
    }

    // NEW: dual-filler usability check — a residual is only truly "safe"
    // if it can host BOTH the next item and a typical (mean-sized) item
    // afterwards; otherwise it is likely to strand space.
    if post_residual > 0 && next_item_size > 0 {
        let after_next = post_residual as i64 - next_item_size as i64;
        if after_next < 0 {
            score += 3.0;
        } else if (after_next as f64) < mean_residual * 0.5 {
            score += 2.0;
        } else if after_next == 0 {
            score -= 6.0;
        }
    }

    // Dynamic time horizon: late in the stream, avoid opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        // Opening is acceptable when few fitting bins exist.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        // Scale opening reluctance with global bin pressure.
        score += 12.0 * pressure;
        // Lookahead synergy: fresh bin can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Opening is more attractive when the fresh bin would host the
        // current item plus a large share of typical future items.
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Penalize opening a new bin when the current item is small relative
        // to capacity (wasteful seeding of a fresh bin).
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        // Opening a fresh bin is more tolerable early in the stream.
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        // With several competing open bins, opening is almost always
        // wasteful — escalate the penalty with fitting_bins_count.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Opening is worse late in the stream when existing open bins
        // still have ample slack relative to the item.
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        // A fresh tight start can pay off when mean residual is large
        // (loose packing so far) and the item is big.
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // If the item nearly fills the fresh bin entirely, opening is
        // essentially free — the residual waste is minimal.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW: opening is cheaper when the fresh bin's leftover would
        // closely match the mean residual (high chance of being reused).
        let fresh_left = bin_capacity - item_size;
        if fresh_left > 0 && mean_residual > 0.0 {
            let reuse_match = 1.0 - ((fresh_left as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 9.0 * reuse_match;
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        // Mid-stream, mildly favor bins whose post-residual matches the next
        // item (probable chain), reducing fragmentation.
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Late-stream strong finishing bonus — residual below next item
        // size means this bin is essentially closed; reward closing early.
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        // Fragmentation guard — mid/late stream, prefer bins whose
        // post-residual remains large enough to be reusable by typical items.
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering — among open bins, mildly favor
        // the emptiest usable bins so that nearly-full bins close out and
        // slack concentrates in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // Late-stream exact-chain boost — near the end, a placement that
        // lets the next item land perfectly is worth extra.
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        // Consolidation depth bonus — when several bins fit the item,
        // prefer the one whose remaining residual best matches the mean
        // residual (future items are statistically most likely to land
        // there), weighted by how many alternatives exist.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: exact-fit ladder — residuals that are exact multiples of
        // common small item sizes (1,2,3,4,5) are prime chain targets;
        // reward them slightly to encourage clean cascades.
        if post_residual > 0 && post_residual <= 20 {
            let div_clean = (post_residual % 5 == 0) || (post_residual % 4 == 0) || (post_residual % 3 == 0);
            if div_clean {
                score -= 2.5;
            }
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item (<= ~10) are pure waste. Penalize "nearly-full but not full" bins.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // Penalize if next item would be stranded by a tiny leftover.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(15) {
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (discourage opening new ones); with few bins, tolerate spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + 2.0 * progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when existing bins fit poorly
    // (i.e., item barely fits or leaves big dead space elsewhere).
    if bin_residual == bin_capacity {
        let tightness = (post_residual as f64 / bin_capacity as f64).abs();
        score += 30.0 - 20.0 * (1.0 - tightness);
        // If item is small, opening a bin wastes capacity; penalize more.
        if item_size < 40 {
            score += 20.0;
        }
    }

    // Slight preference for bins whose residual is close to the item (snug fit).
    let snug = 1.0 - ((bin_residual as f64 - item_size as f64) / bin_capacity as f64);
    score -= 8.0 * snug;

    score
}

