        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // Dead-space ratio targeting — penalize "awkward middle" post-residuals:
    // too large to discard, too small to reliably host future items.
    if post_residual > 0 {
        let gap_ratio = post_frac;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    // Usability-weighted residual — reward post-residuals that sit close to
    // the mean residual (likely to be filled by an upcoming item).
    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
    }

    // Scarcity-weighted consolidation — when only a couple of bins can
    // host the item, closing them down cleanly matters more.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Dead-space waste metric — post-residual measured against the
    // largest plausible future filler (next item). A gap the next item
    // cannot use but that is a substantial fraction of capacity is the
    // dominant source of wasted bins; penalize it proportionally.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_frac;
        score += 14.0 * unusable_frac;
    }

    // NEW: reusability-probability term — a post-residual is only valuable
    // if some plausible item size can still land there. Items range 1..100,
    // so a residual of r is "reachable" with probability ~ r/100. Reward
    // reachable residuals, penalize unreachable ones smoothly.
    if post_residual > 0 {
        let reach = (post_residual as f64 / 100.0).min(1.0);
        score += 6.0 * (1.0 - reach) - 3.0 * reach;
    }

    // NEW: exact-gap match to next item size — a post-residual that is a
    // small positive surplus over the next item is ideal (next item fits
    // and leaves almost nothing). Sharpen the chain reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let surplus = post_residual - next_item_size;
        if surplus <= 4 {
            score -= 8.0;
        } else if surplus <= 12 {
            score -= 3.0;
        }
    }

    // Dynamic time horizon: late in the stream, avoid opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        // Opening is acceptable when few fitting bins exist.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        // Scale opening reluctance with global bin pressure.
        score += 12.0 * pressure;
        // Lookahead synergy: fresh bin can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Opening is more attractive when the fresh bin would host the
        // current item plus a large share of typical future items.
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Penalize opening a new bin when the current item is small relative
        // to capacity (wasteful seeding of a fresh bin).
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        // Opening a fresh bin is more tolerable early in the stream.
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        // With several competing open bins, opening is almost always
        // wasteful — escalate the penalty with fitting_bins_count.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Opening is worse late in the stream when existing open bins
        // still have ample slack relative to the item.
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        // A fresh tight start can pay off when mean residual is large
        // (loose packing so far) and the item is big.
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // If the item nearly fills the fresh bin entirely, opening is
        // essentially free — the residual waste is minimal.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW: opening is also cheap when the resulting fresh-bin residual
        // (capacity - item) is still highly reusable by typical items, i.e.
        // the item is small but the bin keeps a large usable gap AND open
        // bins are nearly exhausted of slack.
        let fresh_gap = bin_capacity - item_size;
        let open_slack_total = mean_residual * open_bins_count as f64;
        if fresh_gap as f64 > 60.0 && open_slack_total < item_size as f64 {
            score -= 6.0;
        }
        // NEW: refuse opening when the best existing fit is decent — the
        // tightest alternative's post-residual proxy via mean comparison.
        if fitting_bins_count >= 2 && fill_frac < 0.5 && t > 0.4 {
            score += 10.0 * t;
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        // Mid-stream, mildly favor bins whose post-residual matches the next
        // item (probable chain), reducing fragmentation.
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Late-stream strong finishing bonus — residual below next item
        // size means this bin is essentially closed; reward closing early.
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        // Fragmentation guard — mid/late stream, prefer bins whose
        // post-residual remains large enough to be reusable by typical items.
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering — among open bins, mildly favor
        // the emptiest usable bins so that nearly-full bins close out and
        // slack concentrates in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // Late-stream exact-chain boost — near the end, a placement that
        // lets the next item land perfectly is worth extra.
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        // Consolidation depth bonus — when several bins fit the item,
        // prefer the one whose remaining residual best matches the mean
        // residual (future items are statistically most likely to land
        // there), weighted by how many alternatives exist.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: closing-velocity bonus — placements that drive a bin's
        // residual toward zero faster are favored when many bins are open,
        // since shrinking the open-bin count compounds future savings.
        if open_bins_count > 4 {
            let closeness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
            score -= 4.0 * closeness * pressure;
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- 2-step lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            // Perfect 2-chain: next item exactly fills this bin
            score -= 60.0;
        } else if post >= nxt {
            // Next item still fits after this placement: good chaining
            score -= 18.0 + 0.25 * (post - nxt);
        } else {
            // Dead space: post_residual too small for the next item
            // Penalize proportionally to how much is wasted relative to nxt
            score += 10.0 + 0.6 * (nxt - post);
        }
    }

    // --- Tightness reward: small post_residual is generally good ---
    score -= 0.15 * (bin_capacity as f64 - post_residual as f64);

    // --- Last-chance bin: strongly favor using it to avoid opening a bin ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // --- Mean residual coupling: prefer bins whose residual is below mean
    //     (pack into the emptiest-feeling tight bins, keep loose bins open) ---
    score += 0.3 * (mean_residual - post_residual as f64);

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Opening a new bin is a big commitment: penalize, but less when
        // the stream is early (future flexibility matters) or many bins are open.
        score += 30.0 - 20.0 * (1.0 - progress) - 1.5 * open_bins_count as f64;
        // If next item is large, a fresh bin is more attractive (it can host it)
        if next_item_size > post_residual {
            score -= 8.0;
        }
    }

    // Mild tie-break noise-free smoothing via item size coupling
    score += 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let gap = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = 1.0 - (gap / cap);
    let is_new_bin = bin_residual == bin_capacity;

    // Hard dead-space penalty: residuals too small for the smallest item are useless.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Reward near-perfect fits with escalating rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space severity is nonlinear: penalize gaps just below common item sizes.
    if gap > 0.0 && gap < 20.0 {
        score += (20.0 - gap) * 1.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Scarcity-weighted consolidation.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Pressure to fill existing bins when many are open (log-scaled).
    let pressure = (open_bins_count as f64).ln() / (1.0 + cap).ln();
    score += (open_bins_count as f64) * 0.3 * (0.5 + progress);
    score -= 10.0 * pressure * tight.max(0.0);

    // Tightness quadratic reward: strong pull toward best fits.
    score -= 18.0 * tight * tight;

    // Dead-space waste metric — gap the next item cannot use.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0 * (gap / cap);
        let gap_frac = gap / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // New-bin candidate block.
    if is_new_bin {
        let fill_frac = item_size as f64 / cap;
        let mean_frac = mean_residual / cap;
        let horizon_cost = 40.0 * (0.25 + progress * progress);
        score = 100.0 + horizon_cost + 25.0;
        if fill_frac > 0.5 {
            score -= 15.0;
        }
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        if fill_frac < 0.4 {
            score += 10.0;
        }
        // Fresh bin synergy: current + next item pair well together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Escalate penalty with competing open bins.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        score += 30.0 * progress * progress;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        score += 12.0 * pressure;
        if progress > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (progress - 0.5);
        }
        if progress < 0.2 && fill_frac > 0.6 {
            score -= 8.0;
        }
        if mean_frac > 0.35 && fill_frac > 0.7 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // NEW: opening is cheap when the fresh bin would host current + next
        // with near-closure, even mid-stream — avoids splitting a pair.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 20.0;
        }
        // NEW: compare fresh-bin waste to the best possible existing fit waste:
        // if the item is huge, existing bins would leave big gaps anyway.
        if fill_frac > 0.8 && gap_of_best_alternative_proxy(mean_residual, cap) > cap * 0.3 {
            score -= 10.0;
        }
        // Small item seeding a fresh bin is wasteful.
        if fill_frac < 0.4 {
            score += 5.0;
        }
    } else {
        // Lookahead: favor bins whose leftover can host the next item, with chain-closure bonus.
        if next_item_size > 0 && post_residual >= next_item_size {
            let second_residual = post_residual - next_item_size;
            let chain_fit = 1.0 - (second_residual as f64 / cap);
            score -= 22.0 * chain_fit;
            if second_residual == 0 {
                score -= 16.0;
            } else if second_residual <= 8 {
                score -= 7.0;
            } else if second_residual < 25 {
                score += 3.0;
            }
            if progress > 0.6 && second_residual == 0 {
                score -= 8.0 * progress;
            }
            if progress > 0.3 && progress <= 0.7 {
                score -= 4.0;
            }
        } else if next_item_size > post_residual && next_item_size <= bin_capacity.saturating_sub(item_size) {
            // Next item cannot chain here but would have fit had the bin been emptier.
            score += 8.0;
        }

        // Mild preference for bins below mean residual (consolidate emptier space).
        score -= (mean_residual - bin_residual as f64) * 0.05;

        // Residual-efficiency steering: concentrate slack in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        if progress > 0.7 && post_residual <= 20 {
            score -= 12.0 * progress;
        }
        if progress > 0.7 && next_item_size > 0 && post_residual < next_item_size {
            score -= 6.0;
        }
        if progress > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - progress);
        }
        // Consolidation depth bonus.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((gap - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // Usability-weighted residual.
        if post_residual > 0 && mean_residual > 0.0 {
            let rel = (gap - mean_residual).abs() / mean_residual;
            score += 4.0 * rel.min(2.0);
        }
        // Awkward-middle gap penalty.
        if post_residual > 0 {
            let gap_ratio = gap / cap;
            if gap_ratio > 0.05 && gap_ratio < 0.30 {
                let mean_gap_dist = (gap - mean_residual).abs() / cap;
                score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
            }
        }
        // NEW: post-residual vs mean-frac steering (from best heuristic).
        let post_frac = gap / cap;
        let mean_frac = mean_residual / cap;
        if post_frac < mean_frac {
            score -= 5.0 * (mean_frac - post_frac);
        } else {
            score += 3.0 * (post_frac - mean_frac);
        }
        // NEW: late-stream exact-chain boost.
        if progress > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * progress;
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

#[inline]
fn gap_of_best_alternative_proxy(mean_residual: f64, cap: f64) -> f64 {
    // Proxy for the gap an existing bin would leave: use mean residual.
    mean_residual.min(cap)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong reward for tight fits (small dead space, non-linear squashing)
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * (1.0 - tight) * 25.0;

    // Exact / near-exact fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // good chain potential, mildly reward closeness of the chain fit
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + chain_slack / 10.0);
        } else if post_residual > 0 && post_residual < next_item_size {
            // dead space that blocks the next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins relative to the current average residual
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Late in the stream, consolidate into existing bins more aggressively
    score += progress * (post_residual as f64) * 0.3;

    // New-bin candidate handling: opening a bin is justified only if the item
    // is large relative to typical residuals or existing bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let poor_fit_elsewhere = (mean_residual < item_size as f64) as i32 as f64;
        let new_bin_cost = 45.0
            - poor_fit_elsewhere * 55.0
            - crowding * 2.0
            - progress * 15.0
            + (post_residual as f64) * 0.25;
        score += new_bin_cost.max(-40.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Perfect / near-perfect fits get escalating rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize creating dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 22.0 * chain_fit;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }
    if next_item_size > post_residual && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score -= 10.0 * pressure * tight;

    // Mean residual coupling: deviating bins get a nudge toward use if they fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Dead-space-aware nudge — prefer bins whose post-residual is small
    // relative to the mean residual (less fragmentation overall).
    let post_frac = post_residual as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    if post_frac < mean_frac {
        score -= 5.0 * (mean_frac - post_frac);
    } else {
        score += 3.0 * (post_frac - mean_frac);
    }

    // Dead-space ratio penalty — post-residual that is too small for the
    // next item but too large to ignore represents wasted space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap_frac = post_residual as f64 / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Two-step lookahead — estimate the residual after hypothetically
    // placing the next item too. Perfect chain-closure is rewarded hard;
    // mid-range awkward gaps are penalized slightly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_residual = post_residual - next_item_size;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // Dead-space ratio targeting — penalize "awkward middle" post-residuals:
    // too large to discard, too small to reliably host future items.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    // Usability-weighted residual — reward post-residuals that sit close to
    // the mean residual (likely to be filled by an upcoming item).
    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
