    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: quadratic penalty on wasted residual, sharpened over stream progress.
    let mut score = post * post / cap;

    // Smooth non-linear coupling: tight fits are rewarded more as stream progresses.
    let tightness = 1.0 - post / cap;
    score -= progress * tightness * tightness * cap * 0.6;

