        score -= 6.0 * scarcity * tight;
    }

    // Dead-space waste metric — post-residual measured against the
    // largest plausible future filler (next item). A gap the next item
    // cannot use but that is a substantial fraction of capacity is the
    // dominant source of wasted bins; penalize it proportionally.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * unusable_frac;
    }

    // NEW (gen 11): residual-shape quality — gaps that are multiples of
    // common small item sizes are reusable; prime-ish awkward gaps are not.
    // Approximate reusability by how close the gap is to the mean residual
    // modulo small offsets, rewarding gaps that sit just under a likely
    // future item rather than just over one.
    if post_residual > 0 && next_item_size > 0 {
        let overhang = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.10 * overhang;
    }

    // Dynamic time horizon: late in the stream, avoid opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        // Opening is acceptable when few fitting bins exist.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        // Scale opening reluctance with global bin pressure.
        score += 12.0 * pressure;
        // Lookahead synergy: fresh bin can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Opening is more attractive when the fresh bin would host the
        // current item plus a large share of typical future items.
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Penalize opening a new bin when the current item is small relative
        // to capacity (wasteful seeding of a fresh bin).
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        // Opening a fresh bin is more tolerable early in the stream.
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        // With several competing open bins, opening is almost always
        // wasteful — escalate the penalty with fitting_bins_count.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Opening is worse late in the stream when existing open bins
        // still have ample slack relative to the item.
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        // A fresh tight start can pay off when mean residual is large
        // (loose packing so far) and the item is big.
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // If the item nearly fills the fresh bin entirely, opening is
        // essentially free — the residual waste is minimal.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW (gen 11): pair-completion check — if the fresh bin would end up
        // with a post-residual that exactly hosts the next item, opening is
        // a clean two-item seed; reward it further.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let seed_gap = bin_capacity - item_size - next_item_size;
            if seed_gap == 0 {
                score -= 18.0;
            } else if seed_gap <= 4 {
                score -= 6.0;
            }
        }
        // NEW (gen 11): if every fitting open bin would leave a worse
        // (smaller, unusable) residual than the fresh-bin seed gap, opening
        // becomes comparatively attractive — approximate via mean residual.
        if mean_frac > 0.5 && fill_frac > 0.5 {
            score -= 9.0 * (mean_frac - 0.5);
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        // Mid-stream, mildly favor bins whose post-residual matches the next
        // item (probable chain), reducing fragmentation.
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Late-stream strong finishing bonus — residual below next item
        // size means this bin is essentially closed; reward closing early.
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        // Fragmentation guard — mid/late stream, prefer bins whose
        // post-residual remains large enough to be reusable by typical items.
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering — among open bins, mildly favor
        // the emptiest usable bins so that nearly-full bins close out and
        // slack concentrates in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // Late-stream exact-chain boost — near the end, a placement that
        // lets the next item land perfectly is worth extra.
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        // Consolidation depth bonus — when several bins fit the item,
        // prefer the one whose remaining residual best matches the mean
        // residual (future items are statistically most likely to land
        // there), weighted by how many alternatives exist.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW (gen 11): exact-fill hunting — when the item leaves a gap that
        // matches the next item exactly, and only few bins can host the item,
        // escalate the chain reward to lock in zero-waste closures.
        if fitting_bins_count <= 2 && next_item_size > 0 && post_residual == next_item_size {
            score -= 10.0;
        }
        // NEW (gen 11): unusable-sliver penalty — leaving a residual in
        // (0, 8) mid-stream creates dead space almost nothing can fill;
        // push such placements away unless it fully closes the bin.
        if t > 0.25 && post_residual > 0 && post_residual < 8 {
            score += 7.0 * t;
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by integer division
    // into capacity-fraction buckets. Small leftovers (tight fits) are valuable.
    let pr = post_residual;
    let class = pr / 10; // 0..=10 harmonic decile of leftover space
    let class_penalty = match class {
        0 => -60.0,           // near-perfect fit (0..=9 left)
        1 => -35.0,           // excellent fit
        2 => -18.0,
        3 => -8.0,
        4 => 0.0,
        5 => 6.0,
        6 => 12.0,
        7 => 18.0,
        8 => 24.0,
        9 => 30.0,
        _ => 36.0,            // barely touched bin
    };
    score += class_penalty;

    // Modulo structure: leftover that is congruent to a "useful" small size class
    // (residual mod 10 == 0) is more likely to be exactly consumed later.
    if pr > 0 && pr % 10 == 0 {
        score -= 8.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the post
    // residual, this is a harmonic pair — reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let nxt = next_item_size as f64;
            // reward proportional closeness of next item to leftover
            let ratio = nxt / pr as f64;
            score -= 20.0 * ratio;
            // dead-space penalty: what remains after both placements
            let after2 = pr as f64 - nxt;
            if after2 > 0.0 && after2 < 10.0 {
                score -= 10.0; // ends in another near-perfect fit
            } else if after2 >= 10.0 && after2 < 20.0 {
                score += 2.0;
            }
        } else {
            // next item cannot use this leftover: mild penalty scaled by waste
            score += 6.0 + 0.05 * (next_item_size as f64 - pr as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if pr <= 20 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has maximal residual. Penalize
    // opening a new bin unless existing bins would waste a lot of space.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // but if all open bins fit badly (large mean residual unused vs item),
        // opening fresh is attractive: discount when item is large relative
        // to mean residual.
        let fit_quality = if mean_residual > 0.0 {
            item_size as f64 / mean_residual
        } else {
            2.0
        };
        if fit_quality > 0.9 {
            score -= 40.0; // existing bins have little room; open new
        }
        if open_bins_count == 0 {
            score -= 55.0; // no alternative
        }
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference to fill bins with larger residual when item is small,
    // keeping tight bins available for small future items.
    let tightness = 1.0 - (bin_residual as f64 / cap);
    score += 5.0 * tightness * (1.0 - item_size as f64 / cap);

    // Keep mean-residual coupling: bins far below mean residual are less
    // attractive targets (save them? no — prefer using roomy bins for big items).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    let is_new_bin = bin_residual == bin_capacity;

    // Escalating rewards for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space penalty: unusable tiny residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Scarcity-weighted consolidation.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Global pressure toward consolidation.
    score += (open_bins_count as f64) * 0.3 * (0.5 + progress);
    score -= 10.0 * pressure * tight.max(0.0);

    // Tightness quadratic reward.
    score -= 18.0 * tight * tight;

    // Dead-space waste: gap the next item cannot use.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0 * (post_residual as f64 / bin_capacity as f64);
        let gap_frac = post_residual as f64 / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Lookahead chain: residual after hypothetically placing next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let second_residual = post_residual - next_item_size;
        let chain_fit = 1.0 - (second_residual as f64 / bin_capacity as f64);
        score -= 22.0 * chain_fit;
        if second_residual == 0 {
            score -= 16.0;
            if progress > 0.6 {
                score -= 8.0 * progress;
            }
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
        if progress > 0.3 && progress <= 0.7 {
            score -= 4.0;
        }
    }

    // Mean residual coupling: prefer consolidating emptier space.
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate block.
    if is_new_bin {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let mean_frac = mean_residual / bin_capacity as f64;
        let horizon_cost = 40.0 * (0.25 + progress * progress);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;

        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        } else if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        score += 12.0 * pressure;

        // Fresh-bin synergy: current + next item pair well together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }

        // Small item seeding a fresh bin is wasteful.
        if fill_frac < 0.4 {
            score += 10.0;
        }
        // Big item early: fresh bin acceptable.
        if progress < 0.2 && fill_frac > 0.6 {
            score -= 8.0;
        }
        // Nearly full fresh bin is essentially free.
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // Late stream with alternatives: extra reluctance.
        if progress > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (progress - 0.5);
        }
        // Fresh tight start pays off when packing has been loose and item is big.
        if mean_frac > 0.35 && fill_frac > 0.7 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // NEW: open a fresh bin only if no open bin's post-residual would
        // beat the fresh bin's residual for the next item (lookahead parity).
        if next_item_size > 0 && fitting_bins_count >= 2 && mean_frac < 0.3 {
            score += 6.0;
        }
    } else {
        // Residual-efficiency steering: concentrate slack in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }

        // Late-stream finishing bonuses.
        if progress > 0.7 && post_residual <= 20 {
            score -= 12.0 * progress;
        }
        if progress > 0.7 && next_item_size > 0 && post_residual < next_item_size {
            score -= 6.0;
        }

        // Fragmentation guard mid/late stream.
        if progress > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - progress);
        }

        // Consolidation depth bonus: residual matching the mean is likeliest
        // to be filled by upcoming items.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }

        // Usability-weighted residual: penalize post-residuals far from mean.
        if post_residual > 0 && mean_residual > 0.0 {
            let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
            score += 4.0 * rel.min(2.0);
        }

        // Awkward-middle gap penalty.
        if post_residual > 0 {
            let gap_ratio = post_residual as f64 / bin_capacity as f64;
            if gap_ratio > 0.05 && gap_ratio < 0.30 {
                let mean_gap_dist = (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;
                score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
            }
        }

        // NEW: two-step lookahead parity — if this bin's post-residual can
        // host the next item but a fresh bin would host it tighter, prefer
        // keeping the fresh bin unopened (implicit via new-bin block).
        if progress > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * progress;
        }
    }

    // Mild deterministic tie-breaker.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (1..100 range, but small items are common) are wasted.
    // Penalize "unusable" gaps (e.g. < 10) heavily and super-linearly.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward near-perfect fits aggressively (tight packing bonus).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Prefer bins whose residual is close to the item (small waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 30.0;

    // Open-bin pressure: when many bins are open, avoid spreading;
    // favor filling existing bins instead of opening new ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when the item fits badly
    // everywhere else (large item relative to typical residuals) or when
    // few bins are open and the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit_elsewhere = (item_size as f64) > mean_residual + 5.0;
        if bad_fit_elsewhere {
            score -= 35.0;
        } else {
            score += 25.0 + progress * 20.0;
        }
        // If the next item could combine with the post-residual in a new bin,
        // slightly favor the new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Lookahead: if placing here leaves exactly room for the next item,
        // reward that chained fit.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            // Leaves a gap the next item can't use: mild penalty.
            score += 8.0;
        }
    }

    // Slight preference for bins with below-average residual (fill fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Perfect / near-perfect fits get escalating rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize creating dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 22.0 * chain_fit;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }
    if next_item_size > post_residual && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score -= 10.0 * pressure * tight;

    // Mean residual coupling: deviating bins get a nudge toward use if they fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Dead-space-aware nudge — prefer bins whose post-residual is small
    // relative to the mean residual (less fragmentation overall).
    let post_frac = post_residual as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    if post_frac < mean_frac {
        score -= 5.0 * (mean_frac - post_frac);
    } else {
        score += 3.0 * (post_frac - mean_frac);
    }

    // Dead-space ratio penalty — post-residual that is too small for the
    // next item but too large to ignore represents wasted space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap_frac = post_residual as f64 / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Two-step lookahead — estimate the residual after hypothetically
    // placing the next item too. Perfect chain-closure is rewarded hard;
    // mid-range awkward gaps are penalized slightly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_residual = post_residual - next_item_size;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // Dead-space ratio targeting — penalize "awkward middle" post-residuals:
    // too large to discard, too small to reliably host future items.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    // Usability-weighted residual — reward post-residuals that sit close to
    // the mean residual (likely to be filled by an upcoming item).
    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
    }

    // Scarcity-weighted consolidation — when only a couple of bins can
    // host the item, closing them down cleanly matters more.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Dead-space waste metric — post-residual measured against the
    // largest plausible future filler (next item).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * unusable_frac;
    }

    // NEW: adaptive waste penalty — scale the unusable-gap penalty by how
    // "hostile" the residual landscape is. When the mean residual is small
    // (tight packing so far), an unusable gap is a bigger outlier and
    // deserves a stronger penalty; when packing is loose, relax it.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let hostility = (0.30 - mean_frac).clamp(0.0, 0.30) / 0.30;
        score += 8.0 * hostility;
    }

    // NEW: gap reusability horizon — a post-residual is only valuable if
    // typical future items can land in it. Reward gaps that sit just above
    // the mean residual (usable by the statistical average item), penalize
    // gaps stranded between the mean and the next item size.
    if post_residual > 0 && mean_residual > 0.0 {
        let mr = mean_residual;
        if post_residual as f64 >= mr * 0.9 && post_residual as f64 <= mr * 1.4 {
            score -= 5.0;
        } else if post_residual as f64 > mr * 1.4 && next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
            score += 5.0;
        }
    }

    // Dynamic time horizon: late in the stream, avoid opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        // Opening is acceptable when few fitting bins exist.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        // Scale opening reluctance with global bin pressure.
        score += 12.0 * pressure;
        // Lookahead synergy: fresh bin can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Opening is more attractive when the fresh bin would host the
        // current item plus a large share of typical future items.
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Penalize opening a new bin when the current item is small relative
        // to capacity (wasteful seeding of a fresh bin).
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        // Opening a fresh bin is more tolerable early in the stream.
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        // With several competing open bins, opening is almost always
        // wasteful — escalate the penalty with fitting_bins_count.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Opening is worse late in the stream when existing open bins
        // still have ample slack relative to the item.
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        // A fresh tight start can pay off when mean residual is large
        // (loose packing so far) and the item is big.
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // If the item nearly fills the fresh bin entirely, opening is
        // essentially free — the residual waste is minimal.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW: when all open fitting bins would leave unusable dead space
        // (post-residual smaller than the next item), opening a fresh bin
        // that pairs current + next item is a genuine consolidation win.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let best_alt_waste = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            if best_alt_waste > 0.0 && fill_frac + (next_item_size as f64 / bin_capacity as f64) > 0.85 {
                score -= 10.0;
            }
        }
        // NEW: mid-stream, opening is slightly cheaper if the fresh bin's
        // leftover after placement matches the mean residual (likely to be
        // reused by the average upcoming item).
        if t > 0.25 && t < 0.7 && mean_residual > 0.0 {
            let fresh_post = bin_capacity - item_size;
            let match_q = 1.0 - ((fresh_post as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 8.0 * match_q;
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        // Mid-stream, mildly favor bins whose post-residual matches the next
        // item (probable chain), reducing fragmentation.
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Late-stream strong finishing bonus.
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        // Fragmentation guard — mid/late stream, prefer bins whose
        // post-residual remains large enough to be reusable by typical items.
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering — among open bins, mildly favor
        // the emptiest usable bins so that nearly-full bins close out and
        // slack concentrates in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // Late-stream exact-chain boost — near the end, a placement that
        // lets the next item land perfectly is worth extra.
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        // Consolidation depth bonus — when several bins fit the item,
        // prefer the one whose remaining residual best matches the mean
        // residual, weighted by how many alternatives exist.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: exact post-residual == next-item match is the strongest
        // consolidation signal at any time — reinforce it globally, scaled
        // by how scarce fitting bins are.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 6.0 / (1.0 + fitting_bins_count as f64);
        }
        // NEW: avoid leaving residuals in the "dead zone" — larger than the
        // next item but smaller than half the mean item gap, unlikely to
        // ever be filled. Weighted by stream progress.
        if next_item_size > 0 && post_residual > next_item_size && (post_residual as f64) < 0.5 * mean_residual.max(1.0) {
            score += 4.0 * t;
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Perfect / near-perfect fits get escalating rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize creating dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 22.0 * chain_fit;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }
    if next_item_size > post_residual && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score -= 10.0 * pressure * tight;

    // Mean residual coupling: deviating bins get a nudge toward use if they fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Dead-space-aware nudge — prefer bins whose post-residual is small
    // relative to the mean residual (less fragmentation overall).
    let post_frac = post_residual as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    if post_frac < mean_frac {
        score -= 5.0 * (mean_frac - post_frac);
    } else {
        score += 3.0 * (post_frac - mean_frac);
    }

    // Dead-space ratio penalty — post-residual that is too small for the
    // next item but too large to ignore represents wasted space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap_frac = post_residual as f64 / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Two-step lookahead — estimate the residual after hypothetically
    // placing the next item too. Perfect chain-closure is rewarded hard;
    // mid-range awkward gaps are penalized slightly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_residual = post_residual - next_item_size;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // Dead-space ratio targeting — penalize "awkward middle" post-residuals:
    // too large to discard, too small to reliably host future items.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    // Usability-weighted residual — reward post-residuals that sit close to
    // the mean residual (likely to be filled by an upcoming item).
    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
    }

    // Scarcity-weighted consolidation — when only a couple of bins can
    // host the item, closing them down cleanly matters more.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Dead-space waste metric — post-residual measured against the
    // largest plausible future filler (next item). A gap the next item
    // cannot use but that is a substantial fraction of capacity is the
    // dominant source of wasted bins; penalize it proportionally.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * unusable_frac;
    }

    // NEW: graceful-gap metric — a residual the next item *almost* fits into
    // is salvageable if a slightly smaller item follows; soften the penalty
    // proportionally to how close the next item is to fitting.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let near_miss = post_residual as f64 / next_item_size as f64;
        if near_miss > 0.75 {
            score -= 5.0 * (near_miss - 0.75);
        }
    }

    // Dynamic time horizon: late in the stream, avoid opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        // Opening is acceptable when few fitting bins exist.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        // Scale opening reluctance with global bin pressure.
        score += 12.0 * pressure;
        // Lookahead synergy: fresh bin can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Opening is more attractive when the fresh bin would host the
        // current item plus a large share of typical future items.
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Penalize opening a new bin when the current item is small relative
        // to capacity (wasteful seeding of a fresh bin).
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        // Opening a fresh bin is more tolerable early in the stream.
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        // With several competing open bins, opening is almost always
        // wasteful — escalate the penalty with fitting_bins_count.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Opening is worse late in the stream when existing open bins
        // still have ample slack relative to the item.
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        // A fresh tight start can pay off when mean residual is large
        // (loose packing so far) and the item is big.
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // If the item nearly fills the fresh bin entirely, opening is
        // essentially free — the residual waste is minimal.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW: comparative-waste gate — opening is justified only if the
        // leftover after placing here beats the average leftover that the
        // existing fitting bins would leave behind. Estimate the best
        // available post-residual among alternatives via mean_residual.
        if fitting_bins_count >= 1 && mean_residual > 0.0 {
            let new_bin_leftover = (bin_capacity - item_size) as f64;
            let alt_leftover = (mean_residual - item_size as f64).max(0.0);
            if new_bin_leftover < alt_leftover - 0.15 * bin_capacity as f64 {
                score -= 14.0 * ((alt_leftover - new_bin_leftover) / bin_capacity as f64).min(1.0);
            } else if new_bin_leftover > alt_leftover {
                score += 10.0 * ((new_bin_leftover - alt_leftover) / bin_capacity as f64).min(1.0);
            }
        }
        // NEW: mid-stream opening requires a large item — small items seeded
        // into fresh bins mid-stream are the top source of dead space.
        if t > 0.35 && t < 0.75 && fill_frac < 0.5 {
            score += 18.0 * (0.5 - fill_frac);
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        // Mid-stream, mildly favor bins whose post-residual matches the next
        // item (probable chain), reducing fragmentation.
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Late-stream strong finishing bonus — residual below next item
        // size means this bin is essentially closed; reward closing early.
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        // Fragmentation guard — mid/late stream, prefer bins whose
        // post-residual remains large enough to be reusable by typical items.
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering — among open bins, mildly favor
        // the emptiest usable bins so that nearly-full bins close out and
        // slack concentrates in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // Late-stream exact-chain boost — near the end, a placement that
        // lets the next item land perfectly is worth extra.
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        // Consolidation depth bonus — when several bins fit the item,
        // prefer the one whose remaining residual best matches the mean
        // residual (future items are statistically most likely to land
        // there), weighted by how many alternatives exist.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: zero-out bonus refinement — closing a bin exactly is worth
        // more as the stream progresses (fewer chances remain to reuse it).
        if post_residual == 0 {
            score -= 10.0 * t;
        }
        // NEW: pair-closure lookahead — placing here and then the next item
        // closes the bin exactly; strongly reward this two-step closure.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 4.0 + 6.0 * t;
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Near-match reward: next item can almost fill the leftover
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 120.0 / (1.0 + slack);
    } else if next_item_size > post_residual {
        // Next item cannot use leftover: penalize proportionally to wasted potential
        let waste = (next_item_size - post_residual) as f64;
        score += 0.5 * waste;
    }

    // Penalize post_residual relative to mean residual (avoid leaving bins with
    // residuals far above average, i.e. poorly packed states)
    score += 0.8 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: this is the only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized so we prefer
    // open bins unless they are genuinely bad fits
    if bin_residual == bin_capacity {
        score += 10.0;
        // Late in the stream, opening a new bin is cheap in bins-per-item terms;
        // early on, discourage bin proliferation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * progress;
        // If the item exactly halves the new bin, that's a decent start
        if (item_size * 2) == bin_capacity {
            score -= 30.0;
        }
    }

    // Tight fit reward: item nearly fills the bin
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness > 0.9 {
        score -= 60.0 * (tightness - 0.9) * 10.0;
    }

    // Fragmentation penalty for tiny dead space that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

