        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // Awkward-middle post-residual penalty.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    // Usability-weighted residual.
    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
    }

    // Scarcity-weighted consolidation.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Unusable-gap waste metric.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * unusable_frac;
    }

    // NEW: harmonic dead-space metric — penalize post-residuals that are
    // neither closable (tiny) nor broadly reusable (large). Measured against
    // both the next item and the mean residual; the compound penalty targets
    // the residual variance weakness diagnosed for this lineage.
    if post_residual > 0 {
        let unusable_by_next = next_item_size > 0 && post_residual < next_item_size;
        let below_mean = post_frac < mean_frac * 0.6;
        if unusable_by_next && below_mean {
            score += 5.0 * post_frac;
        }
    }

    // Dynamic time horizon.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        score += 12.0 * pressure;
        // Fresh bin hosting current + next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // Near-full fresh bin is essentially free.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW: opening a fresh bin to host current + next with a *usable*
        // remainder (>= next-next typical item) is cheaper than the flat
        // estimate suggests; reward proportional to how well the triple fits.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let triple_slack = bin_capacity - item_size - next_item_size;
            if triple_slack >= mean_residual as u32 && triple_slack > 0 {
                score -= 6.0 * (triple_slack as f64 / bin_capacity as f64);
            }
        }
        // NEW: never open when an existing bin would end up nearly full
        // (residual <= 5) — that placement closes a bin for free.
        if post_residual <= 5 {
            score += 45.0;
        }
    } else {
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        // Consolidation depth bonus.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: exact-fill preference — when the item leaves <= 3 slack, this
        // placement effectively retires the bin; reward scaled by pressure.
        if post_residual <= 3 {
            score -= 8.0 + 6.0 * pressure;
        }
        // NEW: avoid splitting pairs — if item + next fits exactly in this
        // bin's residual, strongly prefer keeping them together here.
        if next_item_size > 0 && item_size + next_item_size == bin_residual {
            score -= 14.0;
        }
    }

    // Mild deterministic tie-breaker.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space below the minimum item size (unusable gap).
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 9.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // If next item would fit better in the current residual than post-residual, discourage.
    if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins -> prefer consolidating into existing bins.
    let load_factor = open_bins_count as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 8.0 * load_factor;
    }

    // Mean residual coupling: placing into a bin near the mean residual is neutral;
    // bins far below mean residual are precious, protect them.
    let res_f = bin_residual as f64;
    if res_f > mean_residual + 20.0 {
        score += 3.0; // large bin, don't waste
    } else if res_f < mean_residual - 20.0 {
        score -= 2.0; // small bin, use it up
    }

    // Time horizon: early in stream, be liberal opening bins; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 * progress + 0.5 * (open_bins_count as f64);
    } else {
        score -= 4.0 * progress;
    }

    // Mild preference for filling bins with larger residual when item is large.
    score += 0.05 * (item_size as f64) * (1.0 - res_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0;
    }

    // Lookahead: exact chain fits for the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 22.0 * chain_fit;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }
    if next_item_size > post_residual && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
        score += 8.0;
    }

    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score -= 10.0 * pressure * tight;

    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    let post_frac = post_residual as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    if post_frac < mean_frac {
        score -= 5.0 * (mean_frac - post_frac);
    } else {
        score += 3.0 * (post_frac - mean_frac);
    }

    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap_frac = post_residual as f64 / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    if next_item_size > 0 && next_item_size <= post_residual {
        let second_residual = post_residual - next_item_size;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // NEW refinement: two-step chain closure — after hypothetically placing
    // the next item, check whether the item after that could also fit
    // (approximate by next_item_size again). Deep chain closure is the
    // dominant driver of compaction; reward it proportionally.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_residual = post_residual - next_item_size;
        if second_residual >= next_item_size {
            score -= 4.0 * (second_residual as f64 / next_item_size as f64).min(2.0);
        }
    }

    if post_residual > 0 {
        let gap_ratio = post_frac;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
    }

    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_frac;
        score += 14.0 * unusable_frac;
    }

    // NEW: quantify waste in units of the next item rather than capacity —
    // a residual just below next_item_size wastes nearly a full future
    // placement; scale the penalty by how close it is to being usable.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let near_miss = post_residual as f64 / next_item_size as f64;
        score += 6.0 * (1.0 - near_miss);
    }

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        score += 12.0 * pressure;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW: opening a fresh bin is justified when it can host the current
        // item plus the next one with room left for the mean residual —
        // a "triple-fit" seed. Reward it to encourage high-quality openings.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let seed_slack = bin_capacity - item_size - next_item_size;
            if (seed_slack as f64) >= mean_residual * 0.8 {
                score -= 6.0;
            }
        }
    } else {
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: residual-harvest bonus — late in the stream, strongly prefer
        // placements that leave a post-residual exactly reusable by the
        // mean residual (statistically likely future filler), tightening
        // overall compaction.
        if t > 0.5 && post_residual > 0 && mean_residual > 0.0 {
            let harvest = 1.0 - ((post_residual as f64 - mean_residual).abs() / bin_capacity as f64);
            score -= 3.0 * harvest * t;
        }
    }

    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap; // fraction of bin used after placement

    // Base: prefer tight fits (small post_residual), non-linearly penalized
    let mut score = pr * (1.0 + 0.6 * pr / cap);

    // Smooth polynomial coupling of fill with stream progress:
    // early on, reward high fill mildly; late in stream, reward it strongly
    let coupling = (fill * fill) * (1.0 + 2.5 * progress * progress) * 30.0;
    score -= coupling;

    // Penalize large residuals more as stream progresses (less time to reuse them)
    score += (pr / cap).powi(3) * 40.0 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits in the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        // small penalty if next item cannot use the leftover space
        score += 3.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a bin unless current residuals are poor
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score = 10.0 + openness * 5.0 + 30.0 * (1.0 - progress)
            - 20.0 * ((mean_residual / cap).powi(2));
        // If nothing fits well elsewhere, this becomes attractive
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for spreading across many bins
    score += 0.5 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Perfect / near-perfect fits get escalating rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize creating dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 22.0 * chain_fit;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }
    if next_item_size > post_residual && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score -= 10.0 * pressure * tight;

    // Mean residual coupling: deviating bins get a nudge toward use if they fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Dead-space-aware nudge — prefer bins whose post-residual is small
    // relative to the mean residual (less fragmentation overall).
    let post_frac = post_residual as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    if post_frac < mean_frac {
        score -= 5.0 * (mean_frac - post_frac);
    } else {
        score += 3.0 * (post_frac - mean_frac);
    }

    // Dead-space ratio penalty — post-residual that is too small for the
    // next item but too large to ignore represents wasted space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap_frac = post_residual as f64 / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Two-step lookahead — estimate the residual after hypothetically
    // placing the next item too. Perfect chain-closure is rewarded hard;
    // mid-range awkward gaps are penalized slightly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_residual = post_residual - next_item_size;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // Dead-space ratio targeting — penalize "awkward middle" post-residuals:
    // too large to discard, too small to reliably host future items.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    // Usability-weighted residual — reward post-residuals that sit close to
    // the mean residual (likely to be filled by an upcoming item).
    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
    }

    // Scarcity-weighted consolidation — when only a couple of bins can
    // host the item, closing them down cleanly matters more.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Dead-space waste metric — post-residual measured against the
    // largest plausible future filler (next item). A gap the next item
    // cannot use but that is a substantial fraction of capacity is the
    // dominant source of wasted bins; penalize it proportionally.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * unusable_frac;
    }

    // NEW (gen 12): residual-decay shaping — a post-residual that is
    // "half-dead" (cannot host anything near the mean item size) is the
    // dominant waste source. Penalize proportionally to how far below
    // the mean residual it falls, but only when it is nonzero.
    if post_residual > 0 && mean_residual > 1.0 && (post_residual as f64) < mean_residual {
        let deficit_frac = 1.0 - (post_residual as f64 / mean_residual);
        score += 7.0 * deficit_frac * deficit_frac;
    }

    // NEW (gen 12): multi-future usability estimate — instead of only the
    // immediate next item, estimate how many typical (mean-sized) items
    // the post-residual could still host; reward residual capacity that
    // keeps at least one more placement possible.
    if post_residual > 0 && mean_residual > 0.0 {
        let hosts = (post_residual as f64 / mean_residual.max(1.0)).floor();
        if hosts >= 1.0 {
            score -= 4.0 * (hosts.min(3.0) / 3.0);
        } else {
            // Residual below one mean item: mostly dead weight.
            score += 3.0;
        }
    }

    // Dynamic time horizon: late in the stream, avoid opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        // Opening is acceptable when few fitting bins exist.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        // Scale opening reluctance with global bin pressure.
        score += 12.0 * pressure;
        // Lookahead synergy: fresh bin can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Opening is more attractive when the fresh bin would host the
        // current item plus a large share of typical future items.
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Penalize opening a new bin when the current item is small relative
        // to capacity (wasteful seeding of a fresh bin).
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        // Opening a fresh bin is more tolerable early in the stream.
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        // With several competing open bins, opening is almost always
        // wasteful — escalate the penalty with fitting_bins_count.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Opening is worse late in the stream when existing open bins
        // still have ample slack relative to the item.
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        // A fresh tight start can pay off when mean residual is large
        // (loose packing so far) and the item is big.
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // If the item nearly fills the fresh bin entirely, opening is
        // essentially free — the residual waste is minimal.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW (gen 12): opening is also attractive when the best existing
        // alternative would strand a large awkward gap. Approximate the
        // stranded gap of the best open bin via the mean residual: if the
        // mean residual is small (bins are nearly full), placing elsewhere
        // leaves almost nothing useful behind, so a fresh bin wastes less.
        if mean_frac < 0.10 && fill_frac > 0.5 {
            score -= 9.0 * (0.10 - mean_frac) * 10.0;
        }
        // NEW (gen 12): if the next item cannot fit anywhere in the leftover
        // of a typical open bin (mean residual < next item), a fresh bin
        // that can host both current and next items is a good investment.
        if next_item_size > 0 && mean_residual < next_item_size as f64
            && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        // Mid-stream, mildly favor bins whose post-residual matches the next
        // item (probable chain), reducing fragmentation.
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Late-stream strong finishing bonus — residual below next item
        // size means this bin is essentially closed; reward closing early.
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        // Fragmentation guard — mid/late stream, prefer bins whose
        // post-residual remains large enough to be reusable by typical items.
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering — among open bins, mildly favor
        // the emptiest usable bins so that nearly-full bins close out and
        // slack concentrates in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // Late-stream exact-chain boost — near the end, a placement that
        // lets the next item land perfectly is worth extra.
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        // Consolidation depth bonus — when several bins fit the item,
        // prefer the one whose remaining residual best matches the mean
        // residual (future items are statistically most likely to land
        // there), weighted by how many alternatives exist.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW (gen 12): late-stream zero-waste sweep — when the post-residual
        // is exactly 0 the bin is perfectly closed; late in the stream this
        // is disproportionately valuable because every stranded gap directly
        // becomes an extra bin.
        if post_residual == 0 && t > 0.5 {
            score -= 10.0 * t;
        }
        // NEW (gen 12): near-closure nudge — a post-residual within a few
        // units of the next item size is one step from closing the bin;
        // prefer it over leaving a mid-range gap, especially mid-stream.
        if next_item_size > 0 && post_residual > next_item_size
            && post_residual <= next_item_size + 6 && t > 0.25 {
            score -= 5.0 * t;
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
