    // largest plausible future filler (next item). A gap the next item
    // cannot use but that is a substantial fraction of capacity is the
    // dominant source of wasted bins; penalize it proportionally.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * unusable_frac;
    }

    // NEW: waste-vs-fit tension — when the unusable gap is small in absolute
    // terms but the item is big, the placement is still efficient; soften the
    // unusable-gap penalty using the item's fill fraction.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let fill = item_size as f64 / bin_capacity as f64;
