            score -= 8.0;
        }
        // With several competing open bins, opening is almost always
        // wasteful — escalate the penalty with fitting_bins_count.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Opening is worse late in the stream when existing open bins
        // still have ample slack relative to the item.
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        // A fresh tight start can pay off when mean residual is large
        // (loose packing so far) and the item is big.
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // If the item nearly fills the fresh bin entirely, opening is
        // essentially free — the residual waste is minimal.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW: fresh-bin residual usability — if the leftover after placing
        // the item is close to the mean residual, future items can still
        // fill it, making the opening cheaper.
        let fresh_post = bin_capacity - item_size;
        if fresh_post > 0 && mean_residual > 0.0 {
            let fresh_rel = ((fresh_post as f64) - mean_residual).abs() / mean_residual;
            if fresh_rel < 0.3 {
                score -= 6.0 * (1.0 - fresh_rel);
            }
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
