        // Mid-stream, mildly favor bins whose post-residual matches the next
        // item (probable chain), reducing fragmentation.
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Late-stream strong finishing bonus — residual below next item
        // size means this bin is essentially closed; reward closing early.
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        // Fragmentation guard — mid/late stream, prefer bins whose
        // post-residual remains large enough to be reusable by typical items.
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering — among open bins, mildly favor
        // the emptiest usable bins so that nearly-full bins close out and
        // slack concentrates in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
