    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // (10, 20, 25, 50) are reusable "slots" — reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 {
            score -= 40.0;
        } else if pr % 25 == 0 {
            score -= 25.0;
        } else if pr % 10 == 0 {
            score -= 15.0;
        } else if pr % 5 == 0 {
            score -= 5.0;
        } else {
            // awkward residual: penalize dead space that can't host typical items
            score += 8.0;
        }
    }

    // Small dead space (< smallest plausible item) is waste
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            // next item fits, but leaves what kind of residual?
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 60.0;
            } else {
                score -= 20.0;
            }
        } else {
            // next item cannot fit here: slight penalty for hoarding space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins fit poorly.
    // A fresh bin has huge residual; make it attractive only when item is large
    // relative to residual spread or few bins fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // attractive for large items
        score -= (item_size as f64) * 0.6;
        // if many bins fit the item, prefer reusing one
        if fitting_bins_count > 2 {
            score += 40.0;
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
        // if mean residual is small, open bins are nearly full — new bin is fine
        if mean_residual < 20.0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward tightness (small residual before placement)
        score += (bin_capacity as f64 - bin_residual as f64) * 0.1;
        // reward packing into bins tighter than average
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Modulo coupling between item size class and post residual class:
    // items in the same decade class pack well together
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

