    // the gap size for mid-range gaps, since they accumulate across bins.
    if post_residual > 10 && post_residual < 60 {
        let w = post_residual as f64;
        score += 0.06 * w * w / bin_capacity as f64;
    }

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        score += 12.0 * pressure;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW: opening is more tolerable when the item plus the mean
        // future item nearly fills the fresh bin (predicts good reuse).
        if item_size as f64 + mean_residual >= 0.85 * bin_capacity as f64 {
            score -= 6.0;
        }
    } else {
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: endgame squeeze — when very few bins fit and the stream is
        // late, aggressively reward placements that leave near-zero slack.
        if t > 0.8 && post_residual > 0 && post_residual <= 6 {
            score -= 10.0 * (1.0 - post_residual as f64 / 6.0);
        }
    }

    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than large ones.
    // A residual gap is "dead" if no plausible future item (min size 1, but typical
    // items are large) can use it. Treat gaps below ~15 as increasingly toxic.
    let gap = post_residual as f64;
    if gap > 0.0 {
        if gap <= 15.0 {
            // Small gap: nearly dead space -> strong penalty scaled by how dead it is.
            let deadness = (15.0 - gap) / 15.0; // 1.0 at gap=0, 0.0 at gap=15
            score += deadness * 40.0;
        } else {
            // Larger gaps: mild penalty proportional to wasted fraction of capacity.
            score += (gap / bin_capacity as f64) * 10.0;
        }
    }

    // Perfect fit reward: strongly favor exact closures.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bins pressure: prefer using existing bins when many are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item can still fit here: mild reward for keeping usable space.
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Only prefer it
    // when the current placement would create a very small dead gap in a nearly
    // full bin, or when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if the item is large relative to capacity, opening fresh is fine.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= frac * 25.0;
        // If the best existing fit would leave a tiny dead gap, new bin is attractive;
        // emulate by checking: if this call is the new-bin candidate and item is big,
        // reduce penalty so it can win.
        if item_size > 70 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: if mean residual across open bins is small, bins are
    // nearly full; favor tightening fills (lower post_residual already does this),
    // but add slight reward for not wasting the collective slack.
    score -= (mean_residual - gap).clamp(-20.0, 20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Perfect / near-perfect fits with escalating rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize creating dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 22.0 * chain_fit;
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }
    if next_item_size > post_residual && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln() / (1.0 + bin_capacity as f64).ln();
    score -= 10.0 * pressure * tight;

    // Mean residual coupling: deviating bins get a nudge toward use if they fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Dead-space-aware nudge — prefer bins whose post-residual is small
    // relative to the mean residual (less fragmentation overall).
    let post_frac = post_residual as f64 / bin_capacity as f64;
    let mean_frac = mean_residual / bin_capacity as f64;
    if post_frac < mean_frac {
        score -= 5.0 * (mean_frac - post_frac);
    } else {
        score += 3.0 * (post_frac - mean_frac);
    }

    // Dead-space ratio penalty — post-residual that is too small for the
    // next item but too large to ignore represents wasted space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap_frac = post_residual as f64 / next_item_size as f64;
        score += 9.0 * (1.0 - gap_frac.min(1.0));
    }

    // Two-step lookahead — estimate the residual after hypothetically
    // placing the next item too.
    if next_item_size > 0 && next_item_size <= post_residual {
        let second_residual = post_residual - next_item_size;
        if second_residual == 0 {
            score -= 16.0;
        } else if second_residual <= 8 {
            score -= 7.0;
        } else if second_residual < 25 {
            score += 3.0;
        }
    }

    // Dead-space ratio targeting — penalize "awkward middle" post-residuals.
    if post_residual > 0 {
        let gap_ratio = post_residual as f64 / bin_capacity as f64;
        if gap_ratio > 0.05 && gap_ratio < 0.30 {
            let mean_gap_dist = ((post_residual as f64) - mean_residual).abs() / bin_capacity as f64;
            score += 9.0 * gap_ratio * (0.5 + mean_gap_dist);
        }
    }

    // Usability-weighted residual — reward post-residuals that sit close to
    // the mean residual (likely to be filled by an upcoming item).
    if post_residual > 0 && mean_residual > 0.0 {
        let rel = (post_residual as f64 - mean_residual).abs() / mean_residual;
        score += 4.0 * rel.min(2.0);
    }

    // Scarcity-weighted consolidation.
    if fitting_bins_count >= 1 && post_residual > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 6.0 * scarcity * tight;
    }

    // Dead-space waste metric — post-residual measured against the
    // largest plausible future filler (next item).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unusable_frac = post_residual as f64 / bin_capacity as f64;
        score += 14.0 * unusable_frac;
    }

    // NEW: harmonic usability — a post-residual that is an integer divisor
    // of the next item's size (or capacity) is more likely to be filled
    // exactly by future splits; reward such "friendly" gaps.
    if post_residual > 0 && post_residual < 50 {
        let mut friendly = 0.0;
        if next_item_size > 0 && next_item_size % post_residual == 0 {
            friendly += 4.0;
        }
        if bin_capacity % post_residual.max(1) == 0 {
            friendly += 2.0;
        }
        score -= friendly;
    }

    // Dynamic time horizon: late in the stream, avoid opening new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let horizon_cost = 40.0 * (0.25 + 1.0 * t * t);
        let waste_vs_mean = (bin_capacity as f64 - mean_residual).max(0.0);
        score = 100.0 + horizon_cost - 0.05 * waste_vs_mean;
        // Opening is acceptable when few fitting bins exist.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        } else if fitting_bins_count == 2 {
            score += 6.0;
        }
        // Scale opening reluctance with global bin pressure.
        score += 12.0 * pressure;
        // Lookahead synergy: fresh bin can host current + next item together.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // Opening is more attractive when the fresh bin would host the
        // current item plus a large share of typical future items.
        if mean_frac < 0.25 && (item_size as f64) > 0.5 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Penalize opening a new bin when the current item is small relative
        // to capacity (wasteful seeding of a fresh bin).
        if (item_size as f64) < 0.4 * bin_capacity as f64 {
            score += 10.0;
        }
        // Opening a fresh bin is more tolerable early in the stream.
        if t < 0.2 && item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        // With several competing open bins, opening is almost always
        // wasteful — escalate the penalty with fitting_bins_count.
        if fitting_bins_count >= 3 {
            score += 8.0 + 3.0 * (fitting_bins_count as f64 - 3.0);
        }
        // Opening is worse late in the stream when existing open bins
        // still have ample slack relative to the item.
        if t > 0.5 && fitting_bins_count >= 2 {
            score += 15.0 * (t - 0.5);
        }
        // A fresh tight start can pay off when mean residual is large
        // (loose packing so far) and the item is big.
        if mean_frac > 0.35 && item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 7.0 * (mean_frac - 0.35);
        }
        // If the item nearly fills the fresh bin entirely, opening is
        // essentially free — the residual waste is minimal.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.9 {
            score -= 20.0 * (fill_frac - 0.9);
        }
        // NEW: opening is justified when existing bins' residuals are all
        // too small to pair with the next item, but a fresh bin could host
        // the next item after this one — a genuine capacity gap.
        if next_item_size > 0 && mean_frac > 0.0
            && (mean_residual < next_item_size as f64)
            && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
        // NEW: never open for tiny items when any bin fits — pure waste.
        if item_size <= 10 && fitting_bins_count >= 1 {
            score += 25.0;
        }
    } else {
        // Late stream: reward keeping bins alive and finishing them off.
        if t > 0.7 && post_residual <= 20 {
            score -= 12.0 * t;
        }
        // Mid-stream, mildly favor bins whose post-residual matches the next
        // item (probable chain), reducing fragmentation.
        if t > 0.3 && t <= 0.7 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        // Late-stream strong finishing bonus.
        if t > 0.7 && post_residual < next_item_size as f64 {
            score -= 6.0;
        }
        // Fragmentation guard — mid/late stream, prefer bins whose
        // post-residual remains large enough to be reusable.
        if t > 0.4 && post_residual > 0 && post_residual < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Residual-efficiency steering — concentrate slack in fewer bins.
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // Late-stream exact-chain boost.
        if t > 0.6 && next_item_size > 0 && post_residual == next_item_size {
            score -= 8.0 * t;
        }
        // Consolidation depth bonus.
        if fitting_bins_count >= 2 && post_residual > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((post_residual as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / (fitting_bins_count as f64));
        }
        // NEW: exact-fill trajectory — reward bins where the current item
        // consumes nearly all the residual (bin closes cleanly), scaled by
        // how full the bin already was.
        let used_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        let consume_frac = item_size as f64 / bin_residual.max(1) as f64;
        if consume_frac > 0.8 {
            score -= 6.0 * (consume_frac - 0.8) * (0.5 + used_frac);
        }
        // NEW: avoid leaving a residual just below the smallest useful size —
        // gaps in [1, next_item) that no item can fill are pure loss; the
        // closer the gap to the next item size, the more painful.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let near_miss = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 7.0 * near_miss * near_miss;
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fill (small post_residual)
    score -= 0.5 * (bin_residual as f64 - post_residual as f64); // = item_size, constant per candidate

    // Aggressive 2-step lookahead: perfect match with next item is gold
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = post - nxt;
        if diff == 0.0 {
            score -= 40.0; // exact fit for the next item
        } else if diff > 0.0 {
            // next item fits inside this bin's leftover: reward proportional to closeness
            score -= 20.0 * (1.0 - diff / nxt).max(0.0);
        } else {
            // leftover too small for next item: dead space penalty grows as gap shrinks
            score += 6.0 * (1.0 - (-diff / nxt).min(1.0));
        }

        // If the NEXT item could exactly fill this bin's residual, strong bonus
        if (bin_residual as f64 - nxt).abs() < 0.5 && post_residual == 0 {
            score -= 15.0;
        }
    }

    // Reward leaving post_residual in the "useful" band (items are 1..100, typical small)
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 10.0 {
        score -= 3.0; // small leftovers often reusable
    } else if pr > 60.0 {
        score += 2.0; // large leftover means loose packing
    }

    // Relative to mean residual: prefer bins that end below-average residual (efficiently used)
    score += 0.3 * (mean_residual - pr);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if current item nearly fills a fresh bin, opening is fine
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    score
}

