        // post-residual is at least the mean residual (still reusable by
        // typical items) but penalize leaving exactly-mean-sized gaps that
        // rarely match any single item; steer toward either small (closable)
        // or large (reusable) residuals.
        if post_residual > 0 && mean_residual > 0.0 {
            let pr = post_residual as f64;
            if (pr - mean_residual).abs() < 2.0 && pr > 15.0 {
                score += 3.0;
            }
        }
    }

    // Mild deterministic tie-breaker based on residual ordering.
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fits are ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 120.0;
    } else if post_residual <= 6 {
        score -= 40.0;
    }

    // Harmonic class of post_residual: reusable "slots" rewarded
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 {
            score -= 40.0;
        } else if pr % 25 == 0 {
            score -= 25.0;
        } else if pr % 10 == 0 {
            score -= 15.0;
        } else if pr % 5 == 0 {
            score -= 5.0;
        } else {
            score += 8.0;
        }
    }

    // Small dead space is waste
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead: next item interacts with post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 60.0;
            } else if pr2 <= 8 {
                score -= 30.0;
            } else {
                score -= 20.0;
            }
        } else {
            // next item cannot fit here: dead gap for it
            let gap_frac = pr as f64 / next_item_size as f64;
            score += 5.0 + 9.0 * (1.0 - gap_frac.min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Scarcity-weighted consolidation
    if fitting_bins_count >= 1 && pr > 0 && !is_new_bin {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 12.0 * scarcity;
    }

    if is_new_bin {
        // Base cost of opening a new bin
        score += 30.0;
        // Attractive for large items
        score -= (item_size as f64 / cap) * 70.0;
        // Nearly-full fresh bins are essentially free
        let fill_frac = item_size as f64 / cap;
        if fill_frac > 0.85 {
            score -= 30.0 * (fill_frac - 0.85);
        }
        // Small items should not seed fresh bins
        if fill_frac < 0.4 {
            score += 25.0;
        }
        // Many bins fit the item -> prefer reusing one
        if fitting_bins_count > 2 {
            score += 40.0 + 8.0 * (fitting_bins_count as f64 - 2.0);
        } else if fitting_bins_count == 2 {
            score += 10.0;
        }
        // Late in stream, avoid opening new bins
        score += 45.0 * t * t;
        // If mean residual is small, open bins are nearly full — new bin is fine
        if mean_residual < 20.0 {
            score -= 30.0;
        }
        // Pairing lookahead: fresh bin hosting item + next item is efficient
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
