        score += 0.20 * (bin_residual as f64 - mean_residual);
    }

    // New-bin decision: opening a new bin is expensive early, acceptable late or when no good fit exists
    if is_new_bin {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let item_pressure = (item_size as f64 / bin_capacity as f64).powi(2);
