        if progress > 0.7 && fitting_bins_count >= 1 {
            score += 12.0;
        }
    }

    // Global state: many open bins -> prefer consolidation (favor bins below mean residual)
    if open_bins_count > 3 {
        score += 0.08 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64 - 0.5);
    }

    score
}

