        }
        // Small items should not seed fresh bins
        if fill_frac < 0.4 {
            score += 25.0;
        }
        // Many bins fit the item -> prefer reusing one
        if fitting_bins_count > 2 {
            score += 40.0 + 8.0 * (fitting_bins_count as f64 - 2.0);
        } else if fitting_bins_count == 2 {
            score += 10.0;
        }
        // Late in stream, avoid opening new bins
        score += 45.0 * t * t;
        // If mean residual is small, open bins are nearly full — new bin is fine
        if mean_residual < 20.0 {
            score -= 30.0;
        }
        // Pairing lookahead: fresh bin hosting item + next item is efficient
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
            let pair_slack = bin_capacity - item_size - next_item_size;
            if pair_slack <= 10 {
                score -= 12.0;
            }
        }
        // If existing fitting bins have large residuals, opening is wasteful
        if mean_residual > (item_size as f64) * 1.5 {
            score += 20.0;
        }
        // Fresh-bin slack would exactly host the next item's class: good chain seed
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 40.0;
        }
        // NEW: fresh-bin slack that can host next item plus a small remainder is
        // still a good seed; scale reward by how much of the slack is consumed
        if next_item_size > 0 && bin_capacity - item_size > next_item_size {
            let slack = bin_capacity - item_size;
            let use_frac = next_item_size as f64 / slack as f64;
            if use_frac > 0.6 {
                score -= 18.0 * use_frac;
            }
        }
        // NEW: opening a bin for an item that no residual anywhere could hold well
        // (very large item) is often unavoidable; soften the penalty slightly
        if fill_frac > 0.7 && fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward tightness (small residual before placement)
        score += (cap - bin_residual as f64) * 0.1;
        // Reward packing into bins tighter than average
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
        // Consolidation depth: match post residual to mean residual when alternatives exist
        if fitting_bins_count >= 2 && pr > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((pr as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
