        }
        // Late stream: reward closing bins out
        if t > 0.7 && pr <= 20 {
            score -= 12.0 * t;
        }
        // Fragmentation guard mid/late stream
        if t > 0.4 && pr > 0 && pr < 15 {
            score += 5.0 * (1.0 - t);
        }
        // Late-stream exact-chain boost
        if t > 0.6 && next_item_size > 0 && pr == next_item_size {
            score -= 8.0 * t;
        }
        // Slack steering: concentrate slack in fewer bins
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        // NEW: penalize leaving dead space larger than the next item can use
        if next_item_size > 0 && pr > next_item_size && pr - next_item_size > 15 {
            score += 0.5 * ((pr - next_item_size) as f64 - 15.0);
        }
        // NEW: dead-space decay — residual slack that the next two logical slots
        // (next item, then a mid-size class) cannot consume is progressively worse
        if next_item_size > 0 && pr > 0 {
            let unusable = pr.saturating_sub(next_item_size);
            if unusable > 30 {
                score += 0.35 * (unusable - 30) as f64;
            }
        }
        // NEW: two-stage lookahead — if next item fits leaving pr2, reward pr2 that
        // is itself a harmonic slot (chain of reusable residuals)
        if next_item_size > 0 && next_item_size <= pr {
            let pr2 = pr - next_item_size;
