                score -= 25.0 * t;
            }
        }
    }

    // Class coupling: items pack well with same-decade residuals
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual (decades): tiny leftovers are gold,
    // mid-range leftovers (30-60) are dead space magnets.
    let class = post_residual / 10;
    score += match class {
        0 => -35.0,                       // near-perfect closure
        1 => -12.0,                       // good
        2 => 6.0,                         // mediocre
        3 => 18.0,                        // classic dead zone (30-39)
        4 => 26.0,                        // worst: fits nothing small well
        _ => 20.0,                        // large leftover
    };

    // Modulo-5 fine structure: residuals divisible by 5 pair better with
    // typical item sizes (multiples of 5/10).
    if post_residual % 5 == 0 {
        score -= 4.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead (k=2): reward bins whose leftover can host the next item,
    // extra reward for near-exact pairing.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + 0.4 * slack.recip().min(4.0) * 3.0 - 0.25 * slack;
        if (post_residual - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // leftover can't host next item: mild penalty, worse late in stream
        score += 5.0 + 6.0 * progress;
    }

    // Last-chance bin: if this is the only open bin that fits, using it
    // avoids opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    } else if fitting_bins_count > 1 && bin_residual < bin_capacity {
        // competition exists; slight preference toward tighter bins is
        // already handled by post_residual, add mild crowding bonus
        score -= 2.0;
    }

    // New-bin candidate (pristine bin): score it against its own leftover
    // quality. Prefer opening a new bin only when the item is large enough
    // that the fresh bin's leftover is small, and when few existing bins fit.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        // discourage new bins when many open bins already fit the item
        score += 6.0 * fitting_bins_count as f64;
        // discourage new bins early in the stream when consolidation is cheap
        score += 10.0 * (1.0 - progress);
        // harmonic class of the fresh bin's leftover
        let fresh_class = (bin_capacity - item_size) / 10;
        if fresh_class <= 1 {
            score -= 15.0; // big item into empty bin is excellent
        } else if fresh_class >= 3 {
            score += 8.0; // small item into empty bin wastes capacity
        }
    }

    // Global pressure: when open bins are on average full, slightly prefer
    // reusing them rather than spreading items.
    score += 0.05 * mean_residual * (1.0 - progress);

    score
}

