        if fill_frac < 0.4 {
            score += 25.0;
        }
        if fitting_bins_count > 2 {
            score += 40.0 + 8.0 * (fitting_bins_count as f64 - 2.0);
        } else if fitting_bins_count == 2 {
            score += 10.0;
        }
        score += 45.0 * t * t;
        if mean_residual < 20.0 {
            score -= 30.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 16.0;
            let left = bin_capacity - item_size - next_item_size;
