        // far below the next item (unlikely to be reused) get penalized more
        // strongly as the stream progresses
        if pr > 0 && next_item_size > 0 && (pr as f64) < next_item_size as f64 {
            let shortfall = next_item_size as f64 - pr as f64;
            if shortfall <= 15.0 {
                score += 2.0 * shortfall * (0.3 + 0.7 * t);
