        if pr > 0 {
            let dead_ratio = pr as f64 / bin_capacity as f64;
            if dead_ratio < 0.12 {
                score += 20.0 * (0.12 - dead_ratio) * (0.5 + t);
            }
        }
        // reward leaving a residual close to mean residual
        if pr > 0 && next_item_size > 0 && pr >= next_item_size {
            let reuse = (pr - next_item_size) as f64;
            if reuse > 0.0 && (reuse - mean_residual).abs() < 4.0 {
                score -= 6.0;
            }
        }
        // residual is a small multiple of the next item with little leftover
        if pr > 0 && next_item_size > 0 && next_item_size <= pr {
            let drains = pr / next_item_size;
            let leftover = pr % next_item_size;
            if drains >= 2 && leftover <= 4 {
                score -= 5.0 + 3.0 * drains.min(6) as f64;
            }
            if (off_matches(pr, next_item_size)) {
                score -= 4.0 + 3.0 * t;
            }
        }
