    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let prf = pr as f64;
        if next_item_size == pr {
            score -= 190.0;
        } else if next_item_size <= pr {
            let pr2 = pr - next_item_size;
            if pr2 == 0 {
                score -= 85.0;
            } else if pr2 % 10 == 0 {
