            if pr2 > 0 && pr2 >= next_item_size / 2 {
                score -= 6.0;
            }
            // chain reuse — can the residual host the next item twice?
            if pr >= 2 * next_item_size {
                score -= 8.0 + 4.0 * t;
            }
            // deeper chain — residual hosts item three times
            if pr >= 3 * next_item_size {
                score -= 6.0 + 3.0 * t;
            }
        } else {
            let gap_frac = prf / nxt;
            score += 5.0 + 9.0 * (1.0 - gap_frac.min(1.0));
            if nxt - prf <= 3.0 {
                score -= 12.0;
            }
