        if fill_frac < 0.4 {
            score += 25.0;
        }
        if fitting_bins_count > 2 {
            score += 40.0 + 8.0 * (fitting_bins_count as f64 - 2.0);
        } else if fitting_bins_count == 2 {
            score += 10.0;
        }
        score += 45.0 * t * t;
        if mean_residual < 20.0 {
            score -= 30.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 16.0;
            let left = bin_capacity - item_size - next_item_size;
            if left <= 10 {
                score -= 13.0;
            }
            if left > 0 && left % 5 == 0 {
                score -= 10.0;
            }
            if left >= next_item_size {
                score -= 6.0;
            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 42.0;
        }
        if mean_residual > (item_size as f64) * 1.5 {
            score += 20.0;
        }
        if fitting_bins_count == 1 && item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 13.0;
        }
        if t > 0.6 && item_size > bin_capacity / 2 {
            score -= 20.0 * t;
        }
        let left_after = bin_capacity - item_size;
        if left_after > 0 && left_after < 12 && next_item_size > left_after {
            score += 18.0;
        }
        // Dead-space rescue: relax new-bin penalty when open bins would strand space
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let worst_strand = item_size as f64 >= mean_residual
