            let after = pr - next_item_size;
            if after >= next_item_size {
                score -= 4.0 + 4.0 * t;
            }
            if after >= 20 && after % 10 == 0 {
                score -= 5.0;
            }
        }
        // Variance suppression — homogenize residuals when fragmented
        if pr > 0 && open_bins_count > 5 && mean_residual > 0.0 {
            let dev = (pr as f64 - mean_residual).abs();
            if dev > 10.0 {
                score += 0.25 * (dev - 10.0).min(25.0) * (0.4 + 0.6 * t);
            }
        }
        // Endgame squeeze — late in the stream, prioritize the bin
        // whose residual the next item fills most exactly, overriding slack bias
        if t > 0.8 && pr > 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / 20.0).max(0.0);
        }
        // MUTATION: perfect-fill anticipation — reward bins whose post residual
        // equals a plausible future item size (small residual is easier to close)
        if pr > 0 && pr <= 12 && open_bins_count > 2 {
            score -= 2.0 + 1.5 * (12 - pr) as f64 * (0.3 + 0.7 * t);
