        if pr > 0 && open_bins_count > 5 && mean_residual > 0.0 {
            let dev = (pr as f64 - mean_residual).abs();
            if dev > 10.0 {
                score += 0.25 * (dev - 10.0).min(25.0) * (0.4 + 0.6 * t);
            }
        }
        // Endgame squeeze — late, prioritize the bin whose residual the next
        // item fills most exactly, overriding slack bias
        if t > 0.8 && pr > 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / 20.0).max(0.0);
        }
        // MUTATION: dead-space ratio gradient — replace the coarse dead_ratio
        // penalty with a smooth quadratic that pushes placements toward the
        // smallest possible leftover fraction, weighted by stream progress
        if pr > 0 {
            let dr = pr as f64 / bin_capacity as f64;
            if dr <= 0.30 {
                score += 26.0 * dr * dr * (0.4 + 1.2 * t);
            }
            // MUTATION: stranded-fragment forecast — if the leftover is smaller
            // than any plausible future item (well under the running mean), the
            // space is almost surely dead; tax it progressively
            if pr < 20 && next_item_size > pr && (pr as f64) < 0.5 * mean_residual.max(1.0) {
                score += 8.0 * (1.0 - pr as f64 / 20.0) * (0.5 + t);
            }
        }
        // MUTATION: next-item complement harmony — prefer placements whose
        // leftover after the next item is itself a tight, drainable residue
        if pr > 0 && next_item_size > 0 && pr > next_item_size {
            let after = pr - next_item_size;
            if after > 0 && after < 10 && t > 0.3 {
                score -= 6.0 * (1.0 - after as f64 / 10.0) * (0.5 + t);
            }
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

