                score += 30.0 * (0.3 + 0.7 * t);
            }
        }
        // reward bins whose post residual stays within a reusable band
        // around the mean, scaled by how many bins compete
        if pr > 0 && mean_residual > 0.0 && (pr as f64 - mean_residual).abs() <= 4.0 {
            score -= 3.5 + 2.0 / fitting_bins_count.max(1) as f64;
        }
        // dead-space harvest term — penalize wasted slack above the next item
        if pr > 0 && next_item_size > 0 && pr > next_item_size {
            let excess = pr - next_item_size;
            if excess > 20 && excess < 60 {
                score += 0.08 * (excess as f64 - 20.0);
            }
        }
        // MUTATION: two-item drain forecast — prefer residuals that stay reusable
        if pr > 0 && next_item_size > 0 && pr >= next_item_size {
            let after = pr - next_item_size;
            if after >= next_item_size {
                score -= 4.0 + 4.0 * t;
            }
            if after >= 20 && after % 10 == 0 {
                score -= 5.0;
            }
        }
        // MUTATION: variance suppression — homogenize residuals when fragmented
        if pr > 0 && open_bins_count > 5 && mean_residual > 0.0 {
            let dev = (pr as f64 - mean_residual).abs();
            if dev > 10.0 {
                score += 0.25 * (dev - 10.0).min(25.0) * (0.4 + 0.6 * t);
            }
        }
        // MUTATION: endgame squeeze — late in the stream, prioritize the bin
        // whose residual the next item fills most exactly
        if t > 0.8 && pr > 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / 20.0).max(0.0);
        }
        // MUTATION (gen 31): residual-decay guard — a mid-range residual that
        // neither the next item nor the mean residual can reach is a slow
        // leak; penalize proportionally to its distance from both, stronger
        // in the second half of the stream
        if pr > 0 && next_item_size > 0 && pr > next_item_size {
            let d_next = (pr as f64 - next_item_size as f64).min(20.0);
            let d_mean = (pr as f64 - mean_residual).abs().min(20.0);
            if d_next > 10.0 && d_mean > 10.0 {
                score += 1.5 + 0.15 * (d_next + d_mean - 20.0) * (0.5 + t);
            }
        }
        // MUTATION (gen 31): sharpen the tiny-residual gradient for pr in 3..=8
        // so near-perfect fits beat merely good ones more decisively
        if pr >= 3 && pr <= 8 {
            score -= 2.0 * (9.0 - pr as f64) * (0.6 + 0.4 * t);
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let pr = post_residual;

    // Perfect fills dominate; graded tiny-residual rewards
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 2 {
        score -= 150.0;
    } else if pr <= 4 {
        score -= 100.0;
    } else if pr <= 6 {
        score -= 40.0;
    } else if pr <= 8 {
        score -= 14.0;
    }

    // Reusable residual slots via divisibility
    if pr > 0 {
        if pr % 50 == 0 {
            score -= 42.0;
        } else if pr % 25 == 0 {
            score -= 26.0;
        } else if pr % 20 == 0 {
            score -= 20.0;
        } else if pr % 10 == 0 {
            score -= 16.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        } else {
            score += 7.0;
        }
    }

    // Tiny dead space is waste, worse late in stream
    if pr > 0 && pr < 10 {
        score += 28.0 + 22.0 * t;
    }

    // Fragile leftovers few future items can consume
    if pr > 6 && pr < 20 {
        score += 5.0 + 0.5 * (pr as f64 - 6.0);
    }

    // Two-step lookahead with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let prf = pr as f64;
        if next_item_size == pr {
            score -= 190.0;
        } else if next_item_size <= pr {
            let pr2 = pr - next_item_size;
            if pr2 == 0 {
                score -= 85.0;
            } else if pr2 % 10 == 0 {
                score -= 55.0;
            } else if pr2 <= 8 {
                score -= 32.0;
            } else {
                score -= 18.0;
            }
            if pr2 > 0 && pr2 % 5 == 0 {
                score -= 9.0;
            }
            if pr2 >= 1 && pr2 <= 12 && t > 0.5 {
                score -= 7.0 * t;
            }
            if pr2 > 0 && pr2 >= next_item_size / 2 {
                score -= 6.0;
            }
            if pr >= 2 * next_item_size {
                score -= 8.0 + 4.0 * t;
            }
            if pr >= 3 * next_item_size {
                score -= 6.0 + 3.0 * t;
            }
        } else {
            let gap_frac = prf / nxt;
            score += 5.0 + 9.0 * (1.0 - gap_frac.min(1.0));
            if nxt - prf <= 3.0 {
                score -= 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 75.0;
    }

    // Scarcity-weighted consolidation
    if fitting_bins_count >= 1 && pr > 0 && !is_new_bin {
        score -= 10.0 / fitting_bins_count as f64;
    }

    // Mean residual coupling
    score += 0.2 * (mean_residual - pr as f64);

    if is_new_bin {
        let fill_frac = item_size as f64 / bin_capacity as f64;
