                score -= 6.0 + 10.0 * t;
            }
        }
        // Strong two-item packing in a fresh bin
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair >= 0.95 * bin_capacity as f64 {
                score -= 22.0;
            }
            if pair + next_item_size as f64 <= bin_capacity as f64 {
                score -= 9.0 + 5.0 * t;
            }
        }
        // Fragmentation-aware fresh space
        if open_bins_count > 8 && mean_residual < 15.0 {
            score -= 8.0;
        }
        // discourage fresh bin when an open bin's residual nearly matches item
        if fitting_bins_count >= 1 && mean_residual > 0.0 {
            let near = ((bin_capacity - item_size) as f64 - mean_residual).abs();
            if near <= 6.0 {
                score += 10.0 + 2.0 * (6.0 - near);
            }
        }
        // prefer opening fresh bin when item is large relative to mean residual
        if fitting_bins_count >= 1 && mean_residual > 0.0 {
            let stranded = item_size as f64 / mean_residual.max(1.0);
            if stranded > 2.0 {
                score -= 4.0 * (stranded - 2.0).min(4.0);
            }
        }
        // Fresh-bin dead-space forecast
        if next_item_size > 0 && left_after > 0 && left_after < next_item_size {
            let open_all_bad = fitting_bins_count >= 1
                && mean_residual > 0.0
                && (mean_residual as u32) < item_size;
            if open_all_bad {
                score -= 5.0 + 6.0 * t;
            } else {
                score += 4.0 + 5.0 * t;
            }
        }
        // grade the fresh bin's leftover by next-item tileability
        if next_item_size > 0 && left_after > 0 {
            let la = left_after as f64;
            let nxt = next_item_size as f64;
            if la >= nxt {
                let rem = left_after % next_item_size;
                if rem == 0 {
                    score -= 14.0 + 6.0 * t;
                } else if rem <= 3 {
                    score -= 7.0 + 3.0 * t;
                }
            } else {
