                if rem == 0 { score -= 14.0 + 6.0 * t; }
                else if rem <= 3 { score -= 7.0 + 3.0 * t; }
            } else {
                let shortfall = next_item_size as f64 - la;
                if shortfall <= 8.0 { score += 3.0 + 1.5 * shortfall * (0.4 + t); }
