        }
        // Pair-packing in fresh bin
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair >= 0.95 * bin_capacity as f64 { score -= 22.0; }
            if pair + next_item_size as f64 <= bin_capacity as f64 { score -= 9.0 + 5.0 * t; }
