        if pr > 15 && pr < 45 { score += 0.35 * (pr as f64 - 15.0); }
        if next_item_size > 0 && pr > 0 && pr % next_item_size == 0 { score -= 10.0; }
        if next_item_size > 0 && pr >= next_item_size && pr > 0 {
