            if next_item_size > 0 && (next_item_size as f64) > pr as f64 { score += 3.0 * t; }
        }
        // Adaptive dead-space pressure
        if pr > 0 && next_item_size > 0 && (pr as f64) < next_item_size as f64 {
            let shortfall = next_item_size as f64 - pr as f64;
            if shortfall <= 15.0 {
                score += 2.5 * shortfall * (0.3 + 0.7 * t);
