                score -= 85.0;
            } else if pr2 % 10 == 0 {
                score -= 55.0;
            } else if pr2 <= 8 {
                score -= 32.0;
            } else {
                score -= 18.0;
            }
            if pr2 > 0 && pr2 % 5 == 0 {
                score -= 9.0;
            }
            if pr2 >= 1 && pr2 <= 12 && t > 0.5 {
                score -= 7.0 * t;
            }
            if pr2 > 0 && pr2 >= next_item_size / 2 {
                score -= 6.0;
            }
            if pr >= 2 * next_item_size {
                score -= 8.0 + 4.0 * t;
            }
            if pr >= 3 * next_item_size {
                score -= 6.0 + 3.0 * t;
            }
        } else {
            let gap_frac = prf / nxt;
            score += 5.0 + 9.0 * (1.0 - gap_frac.min(1.0));
            if nxt - prf <= 3.0 {
                score -= 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 75.0;
    }

    // Scarcity-weighted consolidation
    if fitting_bins_count >= 1 && pr > 0 && !is_new_bin {
        score -= 10.0 / fitting_bins_count as f64;
    }

    // Mean residual coupling
    score += 0.2 * (mean_residual - pr as f64);

    if is_new_bin {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0;
        score -= fill_frac * 72.0;
        if fill_frac > 0.85 {
            score -= 35.0 * (fill_frac - 0.85);
        }
        if fill_frac < 0.4 {
            score += 25.0;
        }
        if fitting_bins_count > 2 {
            score += 40.0 + 8.0 * (fitting_bins_count as f64 - 2.0);
        } else if fitting_bins_count == 2 {
            score += 10.0;
        }
        score += 45.0 * t * t;
        if mean_residual < 20.0 {
            score -= 30.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 16.0;
            let left = bin_capacity - item_size - next_item_size;
            if left <= 10 {
                score -= 13.0;
            }
            if left > 0 && left % 5 == 0 {
                score -= 10.0;
            }
            if left >= next_item_size {
                score -= 6.0;
            }
        }
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 42.0;
        }
        if mean_residual > (item_size as f64) * 1.5 {
            score += 20.0;
        }
        if fitting_bins_count == 1 && item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 13.0;
        }
        if t > 0.6 && item_size > bin_capacity / 2 {
            score -= 20.0 * t;
        }
        let left_after = bin_capacity - item_size;
        if left_after > 0 && left_after < 12 && next_item_size > left_after {
            score += 18.0;
        }
        // Dead-space rescue: relax new-bin penalty when open bins would strand space
        if fitting_bins_count >= 1 && next_item_size > 0 {
            let worst_strand = item_size as f64 >= mean_residual
                && mean_residual > 0.0
                && next_item_size as f64 > mean_residual;
            if worst_strand {
                score -= 6.0 + 10.0 * t;
            }
        }
        // Strong two-item packing in a fresh bin
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair >= 0.95 * bin_capacity as f64 {
                score -= 22.0;
            }
            if pair + next_item_size as f64 <= bin_capacity as f64 {
                score -= 9.0 + 5.0 * t;
            }
        }
        // Fragmentation-aware fresh space
        if open_bins_count > 8 && mean_residual < 15.0 {
            score -= 8.0;
        }
        // discourage fresh bin when an open bin's residual nearly matches item
        if fitting_bins_count >= 1 && mean_residual > 0.0 {
            let near = ((bin_capacity - item_size) as f64 - mean_residual).abs();
            if near <= 6.0 {
                score += 10.0 + 2.0 * (6.0 - near);
            }
        }
        // prefer opening fresh bin when item is large relative to mean residual
        if fitting_bins_count >= 1 && mean_residual > 0.0 {
            let stranded = item_size as f64 / mean_residual.max(1.0);
            if stranded > 2.0 {
                score -= 4.0 * (stranded - 2.0).min(4.0);
            }
        }
        // Fresh-bin dead-space forecast
        if next_item_size > 0 && left_after > 0 && left_after < next_item_size {
            let open_all_bad = fitting_bins_count >= 1
                && mean_residual > 0.0
                && (mean_residual as u32) < item_size;
            if open_all_bad {
                score -= 5.0 + 6.0 * t;
            } else {
                score += 4.0 + 5.0 * t;
            }
        }
        // MUTATION: grade the fresh bin's leftover by next-item tileability
        if next_item_size > 0 && left_after > 0 {
            let la = left_after as f64;
            let nxt = next_item_size as f64;
            if la >= nxt {
                let rem = left_after % next_item_size;
                if rem == 0 {
                    score -= 14.0 + 6.0 * t;
                } else if rem <= 3 {
                    score -= 7.0 + 3.0 * t;
                }
            } else {
                let shortfall = nxt - la;
                if shortfall <= 8.0 {
                    score += 3.0 + 1.5 * shortfall * (0.4 + t);
                }
            }
        }
        // MUTATION: near-pair overflow — an open bin may still host the next item
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            let overflow = (item_size + next_item_size - bin_capacity) as f64;
            if overflow <= 10.0 {
                score += 2.0 + 0.4 * overflow;
            }
        }
        // MUTATION: keep packing a lone well-fitting open bin to avoid stranding
        if fitting_bins_count == 1 && open_bins_count <= 3 && mean_residual > 0.0 {
            let waste = mean_residual - item_size as f64;
            if waste > 0.0 {
                score += 3.0 + 0.3 * waste.min(30.0);
            }
        }
    } else {
        score += (bin_capacity as f64 - bin_residual as f64) * 0.1;
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
        if fitting_bins_count >= 2 && pr > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((pr as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / fitting_bins_count as f64);
        }
        if t > 0.7 && pr <= 20 {
            score -= 13.0 * t;
        }
        if t > 0.4 && pr > 0 && pr < 15 {
            score += 5.0 * (1.0 - t);
        }
        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        let tightness = 1.0 - ((pr as f64 - item_size as f64).abs() / 30.0).min(1.0);
