    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
