                if rem == 0 {
                    score -= 16.0 + 7.0 * t;
                } else if rem <= 2 {
                    score -= 8.0 + 3.0 * t;
                } else if rem <= 4 {
                    score -= 4.0 + 2.0 * t;
                }
            } else {
