        let slack = bin_residual as f64 - item_size as f64;
        if slack > mean_residual {
            score += 0.06 * (slack - mean_residual);
        } else {
            score -= 0.06 * (mean_residual - slack);
        }
        let tightness = 1.0 - ((pr as f64 - item_size as f64).abs() / 30.0).min(1.0);
