            }
        }
        // variance suppression — homogenize residuals when fragmented
        if pr > 0 && open_bins_count > 5 && mean_residual > 0.0 {
            let dev = (pr as f64 - mean_residual).abs();
            if dev > 10.0 {
                score += 0.25 * (dev - 10.0).min(25.0) * (0.4 + 0.6 * t);
            }
        }
        // endgame squeeze
        if t > 0.8 && pr > 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / 20.0).max(0.0);
        }
        // MUTATION: stranded-capacity guard — when the item nearly empties the
        // bin (pr tiny) but a sibling bin could absorb the same item with a
        // reusable residual, mildly prefer the emptier outcome late in stream
        if pr > 0 && pr <= 3 && t > 0.45 && fitting_bins_count >= 2 {
            score -= 5.0 + 5.0 * t;
        }
        // MUTATION: residual-to-mean harmonization with lookahead — favor bins
        // whose post-residual lands inside a narrow reusable corridor around
        // the mean residual, scaled by fragmentation pressure
        if pr > 0 && mean_residual > 0.0 && open_bins_count > 3 {
            let dev = (pr as f64 - mean_residual).abs();
            if dev <= 8.0 {
                score -= 2.0 * (1.0 - dev / 8.0) * (0.5 + 0.5 * t);
            }
        }
        // MUTATION: mid-band dead-space penalty — residuals of 30-50 that the
        // next item cannot crack are the main waste source; tax them
        if pr >= 30 && pr <= 50 && next_item_size > 0 && (next_item_size as f64) > pr as f64 {
            score += 7.0 + 5.0 * t;
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that can never fit even the smallest future item (size 1)
    // is only zero-cost if it's 0; small residuals are "dead" if below
    // a plausible future item size. Use a soft threshold around 10-30.
    let dead_threshold = 20.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // from the mean in a useful way (large residual bins absorb big items).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 15.0;

    // Open bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening new bins is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.8;

    // Lookahead: if the next item fits into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving residual that is
        // close to but below next item size (near-miss dead space).
        let gap = next_item_size - post_residual;
        if gap <= 15 {
            score += gap as f64 * 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when the
    // current item is large relative to available residuals or when
    // residuals across bins are small (poor fits everywhere).
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / bin_capacity as f64;
        // Open new bin if mean residual is small (existing bins are full-ish)
        score = 10.0 + avg_fit * 40.0;
        // But if this bin is a last resort, still prefer it over new bin
        if fitting_bins_count == 1 {
            score += 45.0;
        }
        // Early stream: new bins are cheap
        score -= (1.0 - progress) * 15.0;
    }

    score
}

