        if post_residual == next_item_size {
            score -= 60.0; // next item fills this bin exactly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after the lookahead item, non-linearly
            score += slack * 0.6;
        } else {
            // next item won't fit here: dead space risk grows
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.9;
        }
    } else {
        // last item: just minimize waste
        score -= 10.0;
    }

    // Reward tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= 0.5 * (mean_residual - post_residual as f64);
    } else {
        score += 0.3 * ((post_residual as f64) - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item leaves a large,
    // reusable residual or no open bin fits well.
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin
        score += 25.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can serve the next item too
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: open a new bin
        }
        // late in the stream, avoid spreading items across new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for fuller bins overall.
    score -= 0.2 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let pr = post_residual;

    // Strong exact/near-exact fit rewards (compaction driver)
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 2 {
        score -= 145.0;
    } else if pr <= 4 {
        score -= 95.0;
    } else if pr <= 6 {
        score -= 38.0;
    } else if pr <= 8 {
        score -= 12.0;
    }

    // Reusable residual slots via divisibility
    if pr > 0 {
        if pr % 50 == 0 {
            score -= 42.0;
        } else if pr % 25 == 0 {
            score -= 26.0;
        } else if pr % 20 == 0 {
            score -= 20.0;
        } else if pr % 10 == 0 {
            score -= 15.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Tiny dead space is waste, worse late in stream
    if pr > 0 && pr < 10 {
        score += 26.0 + 20.0 * t;
    }

    // Fragile leftovers few future items can consume
    if pr > 6 && pr < 20 {
        score += 4.0 + 0.5 * (pr as f64 - 6.0);
    }

    // Two-step lookahead with next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == pr {
            score -= 185.0;
        } else if next_item_size <= pr {
            let pr2 = pr - next_item_size;
            if pr2 == 0 {
                score -= 82.0;
            } else if pr2 % 10 == 0 {
                score -= 52.0;
            } else if pr2 <= 8 {
                score -= 30.0;
            } else {
