                score -= 8.0;
            }
            if pr2 >= 1 && pr2 <= 12 && t > 0.5 {
                score -= 7.0 * t;
            }
            // multi-drain: residual can host next item repeatedly
            if pr >= 2 * next_item_size {
                score -= 8.0 + 4.0 * t;
            }
            if pr >= 3 * next_item_size {
                score -= 6.0;
            }
        } else {
            let gap_frac = (pr as f64) / nxt;
            score += 5.0 + 9.0 * (1.0 - gap_frac.min(1.0));
            if nxt - pr as f64 <= 3.0 {
                score -= 12.0;
            }
            // residual just below next item is stranded
            if pr > 0 && nxt - pr as f64 <= 15.0 && t > 0.4 {
                score += 2.5 * (nxt - pr as f64) * (0.3 + 0.7 * t);
            }
        }
    }

    // Last-chance bin: strongly favor
