        // MUTATION: penalize bins whose post residual cannot host the next item
        if pr > 0 && next_item_size > 0 && next_item_size > pr && fitting_bins_count > 1 {
            let shortfall = next_item_size - pr;
            if shortfall <= 15 {
                score += 2.5 * shortfall as f64 * (0.3 + 0.7 * t);
