        // MUTATION: residual within reusable band around the mean
        if pr > 0 && mean_residual > 0.0 && (pr as f64 - mean_residual).abs() <= 4.0 {
            score -= 3.0 + 2.0 / fitting_bins_count.max(1) as f64;
