    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.45;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: fraction of stream completed
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong preference for tight fits: exact fit gets a big reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward bins whose residual closely matches the item (best-fit sharpening)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(3);

    // Lookahead coupling: if the next item fits in the post residual,
    // strongly reward this placement (chaining good pairs)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size <= post_residual {
            // proportional reward for how well next item fits the leftover
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * chain_fit;
        } else {
            // next item won't fit here: penalize leaving awkward large gaps
            // that neither chain nor stay useful
            let dead = post_residual as f64 / bin_capacity as f64;
            if next_item_size > post_residual {
                score += 60.0 * dead * (1.0 - t); // early stream: avoid fragmentation
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate (empty bin): penalize opening new bins unless
    // current bins fit poorly or we have many open bins already
    if bin_residual == bin_capacity {
        let avg_tight = (mean_residual - item_size as f64).max(0.0);
        // If existing bins would leave large waste, new bin becomes attractive
        let waste_penalty = if fitting_bins_count > 0 {
            (avg_tight / bin_capacity as f64).powi(2)
        } else {
            0.0
        };
        score += 180.0 - 220.0 * waste_penalty + 8.0 * open_bins_count as f64 * (1.0 - t);
        // Late in stream, discourage opening new bins more aggressively
        score += 120.0 * t;
    }

    // Mild preference for filling fuller bins among equals
    score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Global state: with many open bins, prefer consolidation into low-residual bins
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Small tie-breaker on mean residual divergence: prefer bins near the mean
    // (keeps the bin population homogeneous and flexible)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

