        if t > 0.75 && post_residual > 0 && post_residual <= 8 && open_bins_count > 4 {
            score -= 14.0 * t;
        }
        if t > 0.55 && t <= 0.75 && post_residual > 0 && post_residual <= 6 && open_bins_count > 6 {
            score -= 8.0 * t;
        }
        if post_residual > 0 && post_residual < 4 && t > 0.8 {
            score += 10.0;
        }
        if post_residual > 0 && post_residual < 5 && next_item_size > post_residual {
            score += 9.0 + 6.0 * t;
        }
        // Penalize bins whose post residual cannot host the next item
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual && fitting_bins_count > 1 {
            score += 4.0 + 6.0 * (1.0 - t);
        }
        // Dead-space ratio term
        if post_residual > 0 {
            let dead_ratio = pr / bin_capacity as f64;
            if dead_ratio < 0.12 {
                score += 20.0 * (0.12 - dead_ratio) * (0.5 + t);
            } else if dead_ratio > 0.3 && dead_ratio < 0.5 && next_item_size as f64 > pr {
                score += 3.0;
            }
        }
        // Reward leaving a residual close to mean residual
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let reuse = (post_residual - next_item_size) as f64;
            if reuse > 0.0 && (reuse - mean_residual).abs() < 4.0 {
                score -= 6.0;
            }
        }
        // Prime reuse targets: residual is a small multiple of the next item
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let drains = post_residual / next_item_size;
            let leftover = post_residual % next_item_size;
            if drains >= 2 && leftover <= 4 {
                score -= 5.0 + 3.0 * drains.min(6) as f64;
            }
        }
        // Late-stream exact-fill squeeze
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size && pr < mean_residual && t > 0.5 {
            score += 6.0 * t;
        }
        // near-exact fills dominate ties among fitting bins
        if post_residual > 0 && post_residual <= 25 {
            score -= 4.0 * (1.0 - pr / 25.0);
        }
        // exact complement of the item
        if post_residual == item_size && post_residual > 0 {
            score -= 60.0;
        }
        // penalize placements that leave residual just below a common item class
        if post_residual >= 10 && post_residual <= 19 && next_item_size > post_residual {
            score += 6.0 * t;
        }
        // deepen the near-exact-fill gradient for mid residuals
        if post_residual > 25 && post_residual < 60 {
            score += 0.12 * (post_residual as f64 - 25.0);
            if next_item_size > 0 && (next_item_size as f64) > pr {
                score += 3.0 * t;
            }
        }
        // prefer bins whose residual is a near-multiple of the next item
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            let off = post_residual % next_item_size;
            if off == 1 || off == 2 {
                score -= 4.0 + 3.0 * t;
            }
        }
        // adaptive dead-space pressure
        if post_residual > 0 && next_item_size > 0 && pr < next_item_size as f64 {
            let shortfall = next_item_size as f64 - pr;
            if shortfall <= 15.0 {
                score += 2.5 * shortfall * (0.3 + 0.7 * t);
            } else {
                score += 30.0 * (0.3 + 0.7 * t);
            }
        }
        // residual within reusable band around the mean
        if post_residual > 0 && mean_residual > 0.0 && (pr - mean_residual).abs() <= 4.0 {
            score -= 3.5 + 2.0 / fitting_bins_count.max(1) as f64;
        }
        // dead-space harvest term
        if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
            let excess = post_residual - next_item_size;
            if excess > 20 && excess < 60 {
                score += 0.08 * (excess as f64 - 20.0);
            }
        }
        // Two-item drain forecast — prefer residuals that stay reusable
        if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
            let after = post_residual - next_item_size;
            if after >= next_item_size {
                score -= 4.0 + 4.0 * t;
            }
            if after >= 20 && after % 10 == 0 {
                score -= 5.0;
            }
        }
        // Variance suppression — homogenize residuals when fragmented
        if post_residual > 0 && open_bins_count > 5 && mean_residual > 0.0 {
            let dev = (pr - mean_residual).abs();
            if dev > 10.0 {
                score += 0.25 * (dev - 10.0).min(25.0) * (0.4 + 0.6 * t);
            }
        }
        // Endgame squeeze — prioritize exact next-item fills late in stream
        if t > 0.8 && post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / 20.0).max(0.0);
        }
        // MUTATION: tighter late-stream consolidation — discourage opening spread
        // across many bins when residuals are small and stream is late
        if t > 0.65 && open_bins_count > 6 && post_residual > 0 && post_residual < 30 {
            score -= 5.0 * t;
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = post_residual / 10;
    if post_residual > 0 && item_class == pr_class.min(item_class) && post_residual >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
