                }
            }
        }
        // Near-pair overflow — an open bin may still host the next item
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            let overflow = (item_size + next_item_size - bin_capacity) as f64;
            if overflow <= 10.0 {
                score += 2.0 + 0.4 * overflow;
            }
        }
        // MUTATION: fresh bin only if best open fit would strand too much
        if fitting_bins_count >= 1 {
            let strand = (bin_capacity - item_size) as f64;
            if strand > mean_residual * 1.8 && next_item_size as f64 > mean_residual {
                score -= 5.0 + 6.0 * t;
            }
        }
    } else {
        score += (bin_capacity as f64 - bin_residual as f64) * 0.1;
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
        if fitting_bins_count >= 2 && pr > 0 && mean_residual > 0.0 {
            let match_quality = 1.0 - ((pr as f64 - mean_residual).abs() / (mean_residual + 1.0)).min(1.0);
            score -= 5.0 * match_quality * (1.0 - 1.0 / fitting_bins_count as f64);
