            if pr % next_item_size == 1 || pr % next_item_size == 2 {
                score -= 4.0 + 3.0 * t;
            }
        }
        // near-exact fills dominate ties among fitting bins
        if pr > 0 && pr <= 25 {
            score -= 4.0 * (1.0 - pr as f64 / 25.0);
        }
        // exact complement of the item
        if pr == item_size && pr > 0 {
            score -= 60.0;
        }
        // adaptive dead-space pressure
        if pr > 0 && next_item_size > 0 && (pr as f64) < next_item_size as f64 {
            let shortfall = next_item_size as f64 - pr as f64;
            if shortfall <= 15.0 {
                score += 2.5 * shortfall * (0.3 + 0.7 * t);
            } else {
                score += 30.0 * (0.3 + 0.7 * t);
            }
        }
        // residual within reusable band around the mean
        if pr > 0 && mean_residual > 0.0 && (pr as f64 - mean_residual).abs() <= 4.0 {
            score -= 3.5 + 2.0 / fitting_bins_count.max(1) as f64;
        }
        // MUTATION: two-item drain forecast — prefer residuals that stay reusable
        if pr > 0 && next_item_size > 0 && pr >= next_item_size {
            let after = pr - next_item_size;
            if after >= next_item_size {
                score -= 4.0 + 4.0 * t;
            }
            if after >= 20 && after % 10 == 0 {
                score -= 5.0;
            }
        }
        // MUTATION: variance suppression — homogenize residuals when fragmented
        if pr > 0 && open_bins_count > 5 && mean_residual > 0.0 {
            let dev = (pr as f64 - mean_residual).abs();
            if dev > 10.0 {
                score += 0.25 * (dev - 10.0).min(25.0) * (0.4 + 0.6 * t);
            }
        }
        // MUTATION: endgame squeeze — late in the stream, prioritize the bin
        // whose residual the next item fills most exactly
        if t > 0.8 && pr > 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / 20.0).max(0.0);
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = base;

    // Smooth polynomial coupling: penalize small-but-nonzero residuals more as stream progresses
    let tight = (1.0 - base).powi(3);
    score -= 3.0 * tight * (1.0 - progress);

    // Reward near-perfect fits (post_residual close to 0)
    score -= 2.0 * (1.0 - base).powi(6);

    // Penalize large residuals relative to mean residual (wasteful bins)
    let mean_base = mean_residual / cap;
    score += 1.5 * (base - mean_base).abs();

    // Lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let n = next_item_size as f64 / cap;
        score -= 2.5 * (1.0 - (pr - n * cap).abs() / cap).max(0.0);
    } else if next_item_size > 0 {
        score += 0.5 * (next_item_size as f64 / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // Mild pressure to prefer existing bins over opening new ones as bins accumulate
    if bin_residual == bin_capacity {
        score += 0.8 + 0.3 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

