    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the residual left behind: good chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(30.0); // bonus decays as slack grows
    }

    // Next item does NOT fit in the leftover: penalize creating dead space,
    // especially when the leftover is small (unusable fragment).
    if next_item_size > 0 && post_residual < next_item_size {
        let frag = post_residual as f64;
        score += (30.0 - frag.min(30.0)) * 0.8;
    }

    // Tight fill now (small post_residual) is generally good.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many fitting bins: prefer the one closest to mean residual alignment
    // (leave larger residuals for future items when alternatives exist).
    if fitting_bins_count > 1 {
        score += (post_residual as f64 - mean_residual).abs() * 0.3;
    }

    // New-bin candidate: only attractive when residuals across open bins are
    // already fragmented (low mean residual) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64);
