        // MUTATION: endgame squeeze — late, prioritize exact next-item fills
        if t > 0.8 && pr > 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / 20.0).max(0.0);
        }
        // MUTATION (new): dead-space ratio targeting — penalize residuals whose
        // dead fraction sits in an awkward band (too big to waste, too small to
        // host typical items), scaled by stream progress and fragmentation.
        if pr > 0 {
            let dr = pr as f64 / bin_capacity as f64;
            if dr > 0.05 && dr < 0.2 && next_item_size as f64 > pr as f64 {
                score += 10.0 * (0.2 - dr) * (0.4 + 0.6 * t) * (1.0 + 0.05 * open_bins_count as f64).min(1.5);
            }
            // reward residuals whose dead fraction stays low after placement
            if dr <= 0.05 {
                score -= 4.0 + 8.0 * t;
            }
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Reward exact / near-exact fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // Lookahead: penalize if post_residual can fit the next item (leaving usable
    // space is fine), but reward if post_residual is dead space (too small for
    // anything, since items >= 1 we only penalize when it blocks next item).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // leaves room for the lookahead item
        } else {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
        // If this bin is the only one that fits the next item too, keep it viable.
        if post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // gives a decent fit. Penalize the fresh bin mildly, more so when open bins
    // already exist and mean residual is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0
            + 0.05 * mean_residual
            + 8.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0; // some open bin fits; discourage opening new one
        }
    }

    // Prefer bins with residual below the mean (consolidating fuller bins),
    // leaving larger-capacity bins for bigger future items.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Mild penalty for leaving medium dead space (hard to fill later),
    // calibrated around small item sizes.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small gaps are still usable
    } else if post_residual >= 10 && post_residual < 25 {
        score += 5.0; // awkward mid-range gap
    }

    // Encourage bin consolidation: with many open bins, prefer filling existing ones.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

