            let dev = (pr as f64 - mean_residual).abs();
            if dev > 10.0 {
                score += 0.25 * (dev - 10.0).min(25.0) * (0.4 + 0.6 * t);
            }
        }
        // Endgame squeeze
        if t > 0.8 && pr > 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / 20.0).max(0.0);
        }
        // MUTATION: absolute dead-space budget — charge placements by the true
        // wasted fraction left behind, weighted by how few future items could
        // ever drain it (residual below the observed mean is nearly dead).
        if pr > 0 {
            let cap = bin_capacity as f64;
            let prf = pr as f64;
            let drainable = if next_item_size > 0 && pr >= next_item_size {
                1.0
            } else if mean_residual > 0.0 && prf >= mean_residual {
                0.5
            } else {
                0.0
            };
            let waste_charge = (prf / cap) * (1.0 - drainable);
            score += 55.0 * waste_charge * (0.5 + 0.5 * t);
            // complementary: reward high drainability on large residuals
            if drainable == 1.0 && prf > 40.0 {
                score -= 4.0 + 3.0 * t;
            }
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
