    // Smooth non-linear coupling: post residual penalized more strongly as stream progresses
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * pr * (1.0 + x * x);

    // Reward tight fits (small post_residual) with a smooth non-linear bonus
    score -= (1.0 - x) * (1.0 - x) * 8.0;

