    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward; else mild penalty
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += 0.05 * gap;
        if nxt <= pr {
            score -= 4.0 * (1.0 - gap / cap);
        }
    }

    // Mild penalty for proliferating open bins early on
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

