            let tiles = pr / next_item_size;
            if tiles >= 2 && pr % next_item_size <= 5 {
                score -= 4.0 + 2.0 * t;
            }
        }
        // NEW MUTATION: large-item hoarding guard — when the item is large and
        // leaves a big residual the next item can't use, penalize more when
        // many bins are open (avoid multiplying stranded space)
        if pr > 0 && next_item_size > 0 && next_item_size > pr && item_size > bin_capacity / 2 {
            score += 3.0 + 0.15 * open_bins_count.min(20) as f64;
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

