        if t > 0.8 && pr > 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / 20.0).max(0.0);
        }
        // dead-space ratio gradient
        if pr > 0 && next_item_size > 0 && next_item_size > pr {
            let dead_frac = pr as f64 / bin_capacity as f64;
            if dead_frac > 0.25 {
                score += 4.0 * (dead_frac - 0.25) * (1.0 + open_bins_count.min(20) as f64 * 0.05);
            }
        }
        // pair-completion bonus
        if pr > 0 && next_item_size > 0 && pr > next_item_size {
            let rest = pr - next_item_size;
            if rest >= 10 && rest <= 30 && (rest as f64 - mean_residual).abs() <= 2.0 {
                score -= 8.0;
            }
        }
        // residual cliff guard
        if pr > 0 && next_item_size > 0 && pr < next_item_size {
            let gap = next_item_size - pr;
            if gap <= 6 {
                score += 2.0 + 1.2 * (6 - gap) as f64 * (0.5 + 0.5 * t);
            }
        }
        // MUTATION (gen 40): triple-drain bonus — residual that can host the
        // next item three times is prime consolidation target
        if pr > 0 && next_item_size > 0 && pr >= 3 * next_item_size {
            score -= 4.0 + 5.0 * t;
        }
        // MUTATION (gen 40): residual just below item_size is stranded space;
        // penalize leaving pr in (item/2, item) which few items can use
        if pr > 0 && pr > item_size && pr <= item_size * 2 && next_item_size > pr {
            score += 3.0 + 0.15 * ((item_size * 2 - pr) as f64) * (0.5 + t);
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

