        // host the next item, residuals that keep hosting it become precious
        if pr > 0 && next_item_size > 0 && pr >= next_item_size && fitting_bins_count <= 3 {
            score -= (4.0 - fitting_bins_count as f64) * (2.0 + 3.0 * t);
        }
