                score += 3.0 + 0.25 * (pr as f64 - 20.0) * t;
            }
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residuals that form "useful" classes
    // (multiples of common item sizes) are penalized less.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit: strongly favored
    } else if pr <= 10 {
        -8.0 // small dead space, still acceptable
    } else if pr % 10 == 0 {
        -5.0
    } else if pr % 5 == 0 {
        -2.5
    } else if pr < 20 {
        6.0 // awkward tiny-mid gap
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin is extremely valuable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // harmonic match: next item leaves a residual in a good class
            let npr = post_residual - next_item_size;
            let harmony = if npr % 10 == 0 { 10.0 } else if npr % 5 == 0 { 5.0 } else { 0.0 };
            score -= harmony;
        } else {
            // next item cannot use this residual: residual likely wasted
            score += 4.0;
        }
        // large next item: prefer keeping big residuals open
        if nxt > cap * 0.5 && post > nxt {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize wasting a nearly-full bin's residual when plenty of bins fit.
    if fitting_bins_count > 2 && post > 0 && post <= 15 {
        score += 3.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is
    // chosen only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score = cap * 0.85 + open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 > cap * 0.7 {
            score -= 10.0; // big item coming: fresh bin attractive
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post / cap);

    // Mild preference for bins below mean residual (balance avoidance of
    // fragmentation across the fleet).
    score += 0.15 * (mean_residual - post).max(0.0);

    score
}

