    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a bin early in the stream is cheaper (more items to fill it later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If the only fitting bins would leave unusable dead space, prefer a new bin.
        if post_residual == 0 && item_size > 0 {
            // brand-new bin keeps full residual; handled by base score already
        }
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

