}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the remaining space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Next item fits into the post residual: strong reward, scaled by tightness.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        let tight = 1.0 - slack / bin_capacity as f64;
        score -= 40.0 * tight;
    }
    // Next item cannot use the post residual: penalize dead space, worse when large.
    else if next_item_size > 0 {
        let dead = post_residual.min(next_item_size.saturating_sub(1)) as f64;
        score += 0.5 * dead;
    }

    // Relative to mean residual: prefer bins whose post residual is below average
    // (we are consuming the bin's space faster than the fleet average).
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Small bonus for tight fits overall (low post residual relative to item size).
    if item_size > 0 {
        score += 0.3 * (post_residual as f64 / item_size as f64);
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

