        score -= 30.0;
    }

    // Penalize dead space: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.1 * (next_item_size as f64);
    }
    // If next item almost fits, slight penalty for blocking it.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, softened when open bins are fragmented.
        let mut open_cost = 20.0;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            open_cost += 10.0 * (fitting_bins_count as f64);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        open_cost += 10.0 * progress;
        // If mean residual is large, open bins have room; discourage new bin.
        open_cost += 0.15 * mean_residual;
        // If only this bin can fit the item and mean residual is tiny, new bin ok.
        if fitting_bins_count == 0 {
            open_cost -= 25.0;
        }
        score += open_cost;
    }

    // Mild preference for filling more-fragmented bins when many are open.
    if open_bins_count > 3 {
        let frag = (mean_residual - post_residual as f64).abs();
        score += 0.05 * frag;
    }

    // Time-horizon scaling: early stream, be more exploratory (favor new bins slightly less penalized via small bonus to open bins that are half-full).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let half_full_bonus = (bin_residual as f64 / bin_capacity as f64 - 0.5).abs();
    score += progress * 2.0 * half_full_bonus;

    score
}

