    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate handling: mildly penalize opening bins early, allow late stream
    if bin_residual == bin_capacity {
        let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        let pressure = mean_r / bin_capacity as f64;
        score += 8.0 + 35.0 * pressure * (1.0 - progress) - 20.0 * progress;
