}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it land in?
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * bin_capacity / 4;

    // Perfect / near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 18.0;
    }

    // Modulo arithmetic on post_residual: residual classes divisible by common
    // item granularities (10, 20, 25) remain reusable by future items.
    let pr = post_residual as u64;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0;
        }
        if pr % 20 == 0 {
            score -= 8.0;
        }
        if pr % 25 == 0 {
            score -= 6.0;
        }
        if pr % 50 == 0 {
            score -= 5.0;
        }
        // Odd / prime-hostile residuals create dead space: penalize.
        if pr % 10 != 0 && pr % 5 != 0 {
            score += 6.0;
        }
    }

    // Integer-division thresholds on post_residual bands.
    if post_residual > three_quarter {
        score += 25.0; // bin barely used — wasteful placement
    } else if post_residual > half {
        score += 10.0;
    } else if post_residual > quarter {
        score -= 4.0; // sweet spot: leaves a half-class chunk
    }

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain
        } else if next_item_size < post_residual {
            // Harmonic class match: next item's class divides residual class
            let ni = next_item_size as u64;
            if pr % ni == 0 {
                score -= 20.0;
            } else if post_residual - next_item_size <= 10 {
                score -= 14.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; residual should still be broadly reusable
            score += 4.0;
        }
    } else {
        // Last item: closing a bin fully is free; leftover is worthless.
        if post_residual > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item_size)
    // of potential; only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Waste of the fresh bin if item is small, relative to harmonic classes.
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 0.9;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If several bins already fit the item elsewhere, new bin is unattractive.
        if fitting_bins_count > 0 {
            score += 20.0 + 5.0 * fitting_bins_count as f64;
        }
        // Small items pair well with future items: keep fresh bins for big items.
        if item_size <= quarter {
            score += 12.0;
        } else if item_size >= three_quarter {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: when open bins are on average roomy, discourage
    // leaving this one even roomier (fragmentation avoidance).
    if post_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Many open bins: reward tightening the tightest bins (best-fit flavor).
    if open_bins_count > 4 {
        score -= (bin_residual - post_residual) as f64 * 0.05;
    }

    score
}

