        }
        // variance suppression — homogenize residuals when fragmented
        if pr > 0 && open_bins_count > 5 && mean_residual > 0.0 {
            let dev = (pr as f64 - mean_residual).abs();
            if dev > 10.0 {
                score += 0.25 * (dev - 10.0).min(25.0) * (0.4 + 0.6 * t);
            }
        }
        // endgame squeeze — late, prioritize exact next-item fills
        if t > 0.8 && pr > 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / 20.0).max(0.0);
        }
        // dead-space ratio gradient
        if pr > 0 && next_item_size > 0 && next_item_size > pr {
            let dead_frac = pr as f64 / bin_capacity as f64;
            if dead_frac > 0.25 {
                score += 4.0 * (dead_frac - 0.25) * (1.0 + open_bins_count.min(20) as f64 * 0.05);
            }
        }
        // pair-completion bonus
        if pr > 0 && next_item_size > 0 && pr > next_item_size {
            let rest = pr - next_item_size;
            if rest >= 10 && rest <= 30 && (rest as f64 - mean_residual).abs() <= 2.0 {
                score -= 8.0;
            }
        }
        // residual cliff guard — avoid leaving a residual just below
        // the next item (nearly unusable), strongest mid-stream
        if pr > 0 && next_item_size > 0 && pr < next_item_size {
            let gap = next_item_size - pr;
            if gap <= 6 {
                score += 2.0 + 1.2 * (6 - gap) as f64 * (0.5 + 0.5 * t);
            }
        }
        // MUTATION: dead-space budget — bins whose residual is large but not
        // tileable by the item scale are dead weight; penalize proportionally
        // to how far the residual sits from any multiple of mean_residual.
        if pr > 0 && mean_residual > 0.0 {
            let mr = mean_residual;
            let nearest_mult = (pr as f64 / mr).round() * mr;
            let off = (pr as f64 - nearest_mult).abs();
            if off > 6.0 && pr as f64 > mr {
                score += 0.5 * (off - 6.0).min(20.0) * (0.4 + 0.6 * t);
            } else if off <= 2.0 && pr as f64 >= mr {
                score -= 4.0 + 2.0 * t;
            }
        }
        // MUTATION: chain-drain bonus — reward residuals that can absorb the
        // next item AND whose remainder still exceeds half the item scale,
        // signaling a multi-step drain chain.
        if pr > 0 && next_item_size > 0 && pr >= next_item_size {
            let after = pr - next_item_size;
