                score -= 3.0 + 5.0 * t;
            }
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    // Gaps below ~10 (min plausible item) are pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Moderately small gaps (10..=30) are likely to become dead space too.
    if post_residual >= 10 && post_residual <= 30 {
        score += 0.8 * (30.0 - post_residual as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.2 * (post_residual as f64 - next_item_size as f64);
    }
    // If next item cannot fit the leftover, penalize slightly (wasted opportunity).
    if next_item_size > post_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin unless it's early or pressure is low.
        score += 20.0 + 4.0 * pressure - 10.0 * (1.0 - progress);
    } else {
        // Favor existing bins mildly as open-bin count grows.
        score -= 0.5 * pressure;
    }

    // Slight preference for bins with below-average residual (tighter bins).
    if bin_residual != bin_capacity {
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

