        // the next item twice with a usable remainder is a premium target.
        if pr > 0 && next_item_size > 0 && pr >= 2 * next_item_size {
            let rem3 = pr - 2 * next_item_size;
            if rem3 <= 10 {
                score -= 7.0 + 3.0 * t;
            }
        }
        // MUTATION (gen 44): item-size-aware exactness — reward placements
        // whose post residual matches the current item's size (a recurring
        // class in many streams can chain-fill such bins later).
        if pr > 0 && pr == item_size && t > 0.3 {
            score -= 4.0 * t;
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit bias already via post_residual; sharpen it non-linearly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward near-perfect fits (wasted space <= 10 is gold).
    if post_residual <= 10 {
        score -= 25.0 + (10 - post_residual) as f64 * 2.0;
    } else {
        // Penalize large dead space super-linearly.
        score += (post_residual as f64).powf(1.35) * 0.06;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item can still use leftover space: mild reward scaled by snugness.
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Leftover too small for next item: penalize proportional to dead space.
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 0.15 * waste;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: mild competition penalty to spread load.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // New-bin candidate logic: opening a bin is expensive; only attractive when
    // the item is large relative to residual of typical open bins, or when
    // existing bins would leave big dead space, or early stream with few bins.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 40.0;
        // Cheaper to open when few bins are open (consolidation still possible).
        score -= 6.0 * (open_bins_count as f64).min(5.0);
        // Large items benefit from a fresh bin when mean residual is small.
        let mean_r = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if (item_size as f64) > mean_r + 15.0 {
            score -= 25.0;
        }
        // Late in the stream, prefer closing out existing bins rather than opening.
        score += 20.0 * t;
        // If no existing bin fits well (post_residual of best would be large),
        // the new-bin call competes naturally via its low post_residual.
        if post_residual + item_size as f64 <= bin_capacity as f64 && item_size >= 70 {
            score -= 10.0; // huge items pack cleanly in fresh bins
        }
    } else {
        // Placing into an existing bin: reward keeping bin count low.
        score -= 5.0;
        // Reward moving toward mean residual (balance across bins).
        score -= 0.5 * (post_residual as f64 - mean_residual).abs().min(20.0);
    }

    // Global pressure: many open bins with high mean residual -> consolidate harder.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 0.1 * mean_residual;
    }

    // Small early-stream bonus for filling bins aggressively.
    if t < 0.2 && bin_residual < bin_capacity {
        score -= 3.0 * (1.0 - t * 5.0);
    }

    score
}

