            } else if after2 % next_item_size == 0 {
                score -= 7.0 + 4.0 * t;
            }
        }
        if pr > 0 && item_size <= 20 {
            let dead_ratio = pr as f64 / bin_capacity as f64;
            score += 6.0 * dead_ratio * (1.0 - t);
        }
        // MUTATION (gen 45): combinatorial drain count — reward bins whose residual
        // can be tiled almost exactly by the next item, scaled by tile count and
        // stream position; penalize near-misses that strand a sliver
        if pr > 0 && next_item_size > 0 && next_item_size <= pr {
            let tiles = pr / next_item_size;
            let rem = pr % next_item_size;
