            let use_frac = item_size as f64 / bin_residual as f64;
            if use_frac > 0.7 {
                score -= 10.0 * (use_frac - 0.7) * (0.5 + t);
            } else if use_frac < 0.3 && open_bins_count > 5 {
                score += 4.0 * (0.3 - use_frac) * (0.5 + 0.5 * t);
            }
        }
    }

    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    score += open_bins_count as f64 * 0.5;
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += poly * cap * 0.5;
    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * progress * 8.0;
    // Penalize bins with large residuals relative to mean (fragmentation)
    score += (mean_residual - pr).abs() * 0.05;
    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    // Lookahead: penalize leaving residual too small for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 && pr < nx {
            score += (nx - pr) * 0.3;
        } else if pr >= nx {
            score -= 2.0;
        }
    }
    // Mild preference to fill existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }
    score
}

