        // MUTATION: endgame squeeze — late, prioritize exact next-item fills
        if t > 0.8 && pr > 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / 20.0).max(0.0);
        }
        // MUTATION: dead-space ratio gradient
        if pr > 0 && next_item_size > 0 && next_item_size > pr {
            let dead_frac = pr as f64 / bin_capacity as f64;
            if dead_frac > 0.25 {
                score += 4.0 * (dead_frac - 0.25) * (1.0 + open_bins_count.min(20) as f64 * 0.05);
            }
        }
        // MUTATION: pair-completion bonus
        if pr > 0 && next_item_size > 0 && pr > next_item_size {
            let rest = pr - next_item_size;
            if rest >= 10 && rest <= 30 && (rest as f64 - mean_residual).abs() <= 2.0 {
                score -= 8.0;
            }
        }
        // MUTATION: residual cliff guard — avoid leaving a residual just below
        // the next item (nearly unusable), strongest mid-stream
        if pr > 0 && next_item_size > 0 && pr < next_item_size {
            let gap = next_item_size - pr;
            if gap <= 6 {
                score += 2.0 + 1.2 * (6 - gap) as f64 * (0.5 + 0.5 * t);
            }
        }
        // MUTATION (gen45): triple-drain forecast — reward residuals that can
        // host the next item twice more (deep tileability), scaled by progress
        if pr > 0 && next_item_size > 0 && next_item_size > 0 && pr >= 3 * next_item_size {
            let rem3 = pr - 3 * next_item_size;
            if rem3 <= 4 {
                score -= 6.0 + 5.0 * t;
            }
        }
        // MUTATION (gen45): residual-vs-mean parity — when many bins are open,
        // prefer placements that pull residuals toward the mean so future items
        // fit a predictable slot; skip when few bins (no statistical signal)
        if pr > 0 && open_bins_count > 3 && mean_residual > 0.0 {
            let pull = 1.0 - ((pr as f64 - mean_residual).abs() / (mean_residual + 2.0)).min(1.0);
            score -= 2.5 * pull * pull * (0.4 + 0.6 * t);
        }
        // MUTATION (gen45): exact dead-space kill — strongly prefer the bin
        // whose post residual is exactly the mean residual's integer part
        if pr > 0 && mean_residual >= 1.0 && pr as f64 == mean_residual.floor() {
            score -= 4.0 + 4.0 * t;
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size buckets (capacity fractions)
    let item_class = (item_size * 4) / bin_capacity; // 0..3
    let next_class = (next_item_size * 4) / bin_capacity;

    // Perfect / near-perfect fit rewards (non-linear)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Dead-space penalty: post residual in a "useless" harmonic band
    // (too small for typical items 10..80, i.e. post_residual < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 50.0 - post_residual as f64;
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact two-item harmonic match bonus
            let slack = post_residual - next_item_size;
            score -= 80.0 - (slack as f64).min(40.0);
            if slack == 0 {
                score -= 150.0;
            }
        } else {
            // penalize blocking the next item slightly
            score += 10.0 + 0.25 * (next_item_size - post_residual) as f64;
        }
        // harmonic class pairing: big item followed by small item prefers tight bins
        if item_class >= 2 && next_class <= 1 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tightest (already via post_residual)
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 30.0;
        // if item is large, opening a new bin is reasonable
        if item_class >= 2 {
            score -= 25.0;
        }
        // if existing bins are crowded (low mean residual), new bin attractive
        if mean_residual < item_size as f64 {
            score -= 40.0;
        }
        // early in stream, cheaper to open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if only one fitting bin exists, prefer it over a new bin
        if fitting_bins_count == 1 {
            score += 200.0;
        }
    } else {
        // using an existing bin is generally good; scale by fill fraction
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= 15.0 * fill;
    }

    // modulo harmonic tie-breaker on post_residual classes
    let pr_mod = post_residual % 10;
    if pr_mod == 0 && post_residual > 0 {
        score -= 8.0; // round residual is reusable
    } else if pr_mod >= 7 {
        score += 3.0; // awkward residual
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
