    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; anything below ~10 is unlikely to be filled later.
    let dead_threshold: f64 = 8.0;
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if pr <= dead_threshold {
        // quadratic penalty on unusable slivers
        score += (dead_threshold - pr) * (dead_threshold - pr) * 2.5 + 20.0;
    }

    // Reward tight fits (small but still usable residuals)
    if post_residual > 0 && post_residual < item_size.min(20) {
        score -= 12.0;
    }

    // Lookahead: if the next item fits into the post-residual, this placement
    // chains nicely; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size <= bin_residual {
            // placing here would break the next item's fit in this bin
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing
    // ones; new empty bin (residual == capacity) gets penalized more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
    } else {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Slight preference toward bins with below-average residual (keep big
    // residuals available for large future items).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

