        }
        // discourage fresh bin when an open bin's residual nearly matches item
        if fitting_bins_count >= 1 && mean_residual > 0.0 {
            let near = ((bin_capacity - item_size) as f64 - mean_residual).abs();
            if near <= 6.0 {
