        // fresh bin can absorb item + two more next-item-sized loads
        if next_item_size > 0 {
            let triple = item_size as u32 + 2 * next_item_size;
            if triple <= bin_capacity {
                let left3 = bin_capacity - triple;
                score -= 6.0 + 4.0 * t;
                if left3 <= 6 {
                    score -= 6.0;
                }
            }
