        if pr > 15 && pr < 45 {
            score += 0.35 * (pr as f64 - 15.0);
        }
        if next_item_size > 0 && pr > 0 && pr % next_item_size == 0 {
            score -= 10.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr > 0 {
            score -= 6.0;
            if pr - next_item_size <= 5 {
                score -= 11.0;
            }
        }
        if t > 0.6 && pr > 0 && pr <= item_size / 4 {
            score -= 10.0 * t;
        }
        if t > 0.75 && pr > 0 && pr <= 8 && open_bins_count > 4 {
            score -= 14.0 * t;
        }
        if t > 0.55 && t <= 0.75 && pr > 0 && pr <= 6 && open_bins_count > 6 {
            score -= 8.0 * t;
        }
        if pr > 0 && pr < 4 && t > 0.8 {
            score += 10.0;
        }
        if pr > 0 && pr < 5 && next_item_size > pr {
            score += 9.0 + 6.0 * t;
        }
        // Penalize placements that leave residual just below the next item
        if pr > 0 && next_item_size > 0 && next_item_size > pr && fitting_bins_count > 1 {
            score += 4.0 + 6.0 * (1.0 - t);
        }
        // Dead-space ratio term
        if pr > 0 {
            let dead_ratio = pr as f64 / bin_capacity as f64;
            if dead_ratio < 0.12 {
                score += 20.0 * (0.12 - dead_ratio) * (0.5 + t);
            } else if dead_ratio > 0.3 && dead_ratio < 0.5 && next_item_size as f64 > pr as f64 {
                score += 3.0;
            }
        }
        // Reward leaving a residual close to mean residual
        if pr > 0 && next_item_size > 0 && pr >= next_item_size {
            let reuse = (pr - next_item_size) as f64;
            if reuse > 0.0 && (reuse - mean_residual).abs() < 4.0 {
