            }
        }
        // MUTATION: pair-completion bonus
        if pr > 0 && next_item_size > 0 && pr > next_item_size {
            let rest = pr - next_item_size;
            if rest >= 10 && rest <= 30 && (rest as f64 - mean_residual).abs() <= 2.0 {
                score -= 8.0;
            }
        }
        // MUTATION: residual cliff guard — avoid leaving a residual just below
        // the next item (nearly unusable), strongest mid-stream
        if pr > 0 && next_item_size > 0 && pr < next_item_size {
            let gap = next_item_size - pr;
            if gap <= 6 {
                score += 2.0 + 1.2 * (6 - gap) as f64 * (0.5 + 0.5 * t);
            }
        }
        // MUTATION (new): chain-drain bonus — reward residuals that can host
        // the next item AND still match the mean residual band afterwards,
        // keeping the residual pool homogeneous for future items
        if pr > 0 && next_item_size > 0 && pr >= next_item_size {
            let after = pr - next_item_size;
            if after > 0 && mean_residual > 0.0 && (after as f64 - mean_residual).abs() <= 3.0 {
                score -= 4.0 + 3.0 * t;
            }
        }
        // MUTATION (new): mid-band dead-space pressure — residuals in the
        // awkward 30-45 band rarely drain cleanly; penalize more when many
        // bins are already open
        if pr >= 30 && pr <= 45 && open_bins_count > 6 {
            score += 2.0 + 0.3 * (open_bins_count as f64 - 6.0).min(12.0);
        }
    }

    // Class coupling
    let item_class = item_size / 10;
    let pr_class = pr / 10;
    if pr > 0 && item_class == pr_class.min(item_class) && pr >= item_size {
        score -= 5.0;
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact two-item matches
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin fully closed after next item
        } else if post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            // reward small leftover after the lookahead item
            score -= 40.0 * (1.0 - after_next as f64 / bin_capacity as f64);
            if after_next < 10 {
                score -= 15.0; // nearly-dead space is fine if tiny
            }
        } else {
            // next item won't fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Prefer tight fits for the current item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Penalize residuals far from mean (avoid fragmenting average bins)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: keep it attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmented = mean_residual < 0.35 * bin_capacity as f64;
        if fragmented && open_bins_count > 0 {
            score -= 20.0; // open a fresh bin when existing ones are shredded
        } else {
            score += 15.0 + 10.0 * (1.0 - progress); // early stream: prefer filling open bins
        }
    }

    // Mild penalty for leaving medium-size unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny dead space is acceptable (sealed bin)
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 6.0; // awkward residual band: hard to fill later
    }

    score
}

