            }
            if after >= 20 && after % 10 == 0 {
                score -= 6.0;
            }
        }
        // Variance suppression when fragmented
        if pr > 0 && open_bins_count > 5 && mean_residual > 0.0 {
            let dev = (pr as f64 - mean_residual).abs();
            if dev > 10.0 {
                score += 0.25 * (dev - 10.0).min(25.0) * (0.4 + 0.6 * t);
            }
        }
        // Near-exact fills dominate ties
        if pr > 0 && pr <= 25 {
            score -= 4.0 * (1.0 - pr as f64 / 25.0);
        }
        // Residual cliff guard
        if pr > 0 && next_item_size > 0 && pr < next_item_size {
            let gap = next_item_size - pr;
            if gap <= 6 {
                score += 2.0 + 1.2 * (6 - gap) as f64 * (0.5 + 0.5 * t);
            }
        }
        // MUTATION: mid-stream consolidation — drain mid-size residuals early
        // so they don't strand late; graded by residual size
        if pr > 20 && pr < 50 && t < 0.6 {
            score -= 0.4 * (50.0 - pr as f64) * (1.0 - t);
        }
        // MUTATION: endgame exact-fill squeeze
        if t > 0.8 && pr > 0 && next_item_size > 0 && next_item_size <= pr {
            score -= 3.0 * (1.0 - (pr - next_item_size) as f64 / 20.0).max(0.0);
        }
        // MUTATION: pair-completion bonus
        if pr > 0 && next_item_size > 0 && pr > next_item_size {
            let rest = pr - next_item_size;
            if rest >= 10 && rest <= 30 && (rest as f64 - mean_residual).abs() <= 2.0 {
                score -= 8.0;
            }
        }
    }

    // Consolidation pressure when many bins open
    score += open_bins_count as f64 * 0.5;

    // Deterministic tie-breaker
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large wasted space quadratically (dead space is hard to reuse).
    let waste = post_residual as f64;
    score += 0.05 * waste * waste / 100.0;

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item uses leftover
            let next_fit = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 15.0 * next_fit;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.1 * over;
        }
    } else {
        // Last item: prefer closing bins tightly, reward any placement.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is costly unless the item
    // is large and nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin, reduced for large items early on.
        let mut open_cost = 60.0;
        open_cost -= 30.0 * item_frac;
        // Late in the stream, prefer reusing existing bins more aggressively.
        open_cost += 30.0 * progress;
        // If many bins are open already, discourage yet another one.
        open_cost += 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If no open bin fits at all (this call is the only candidate),
        // fitting_bins_count reflects only the new bin; soften cost.
        if fitting_bins_count <= 1 {
            open_cost -= 20.0;
        }
        score += open_cost;
    }

    // Global state coupling: if mean residual is high, bins are loose;
    // prefer placing into bins whose residual is below mean (tighter bins),
    // i.e. penalize bins with residual above the mean.
    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.08 * diff;
    }

    // Slight preference for keeping bin count low: reward placements into
    // existing bins proportionally to how full they already are.
    if bin_residual < bin_capacity {
        let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 10.0 * fullness;
    }

    score
}

